		expect( utils._getDepthCompare( { depthTest: true, depthFunc: LessEqualDepth } ) ).toBe( GPUCompareFunction.GreaterEqual );
	} );

	it( 'logs unsupported enumeration values and returns undefined', () => {
		const { utils } = createBackend();
		const errorSpy = jest.spyOn( console, 'error' ).mockImplementation( () => {} );

		expect( utils._getBlendFactor( 999 ) ).toBeUndefined();
		expect( utils._getBlendOperation( 999 ) ).toBeUndefined();
		expect( utils._getStencilCompare( { stencilFunc: 999 } ) ).toBeUndefined();
		expect( utils._getStencilOperation( 999 ) ).toBeUndefined();
		expect( utils._getDepthCompare( { depthTest: true, depthFunc: 999 } ) ).toBeUndefined();
		expect( errorSpy ).toHaveBeenCalledTimes( 5 );

		errorSpy.mockRestore();
	} );

} );
