		expect( created.render.depthStencil ).toMatchObject( {
			format: 'depth24plus',
			depthWriteEnabled: true,
			depthCompare: GPUCompareFunction.LessEqual,
			stencilReadMask: 0xff,
			stencilWriteMask: 0x0f,
			depthBias: 2,
			depthBiasSlopeScale: 3,
			depthBiasClamp: 0,
			stencilFront: {
				compare: GPUCompareFunction.LessEqual,
				failOp: GPUStencilOperation.Keep,
				depthFailOp: GPUStencilOperation.Replace,
				passOp: GPUStencilOperation.IncrementClamp
			}
		} );
		expect( data.get( pipeline ).pipeline ).toEqual( { kind: 'renderPipeline', descriptor: created.render } );
	} );

	it( 'uses the current color format when rendering to the default framebuffer', () => {
		const { utils, backend, device, data, created } = createBackend();
		const vertexProgram = {};
		const fragmentProgram = {};
		const pipeline = { vertexProgram, fragmentProgram };
		data.set( vertexProgram, { module: { name: 'v' } } );
		data.set( fragmentProgram, { module: { name: 'f' } } );
		const renderObject = {
			object: { isMesh: true, matrixWorld: { determinantAffine: () => 1 } },
			material: makeMaterial( { id: 8, stencilWrite: false, depthWrite: false, polygonOffset: false } ),
			geometry: { index: null },
			pipeline,
			context: { textures: null, depth: false, stencil: false, sampleCount: 1 },
			getBindings: () => []
		};

		utils.createRenderPipeline( renderObject, null );

		expect( backend.utils.getCurrentColorFormat ).toHaveBeenCalledWith( renderObject.context );
		expect( created.render.fragment.targets ).toEqual( [ {
			format: 'bgra8unorm', blend: undefined, writeMask: GPUColorWriteFlags.All
		} ] );
		expect( created.render.depthStencil ).toBeUndefined();
		expect( created.render.multisample.count ).toBe( 1 );
	} );

	it( 'resolves async render pipeline promises even when pipeline creation throws', async () => {
		const { utils, backend, device, data } = createBackend();
		const errorSpy = jest.spyOn( console, 'error' ).mockImplementation( () => {} );
		const vertexProgram = { code: '', stage: 'vertex' };
		const fragmentProgram = { code: '', stage: 'fragment' };
		const pipeline = { vertexProgram, fragmentProgram };
		data.set( vertexProgram, { module: { getCompilationInfo: async () => ( { messages: [] } ) } } );
		data.set( fragmentProgram, { module: { getCompilationInfo: async () => ( { messages: [] } ) } } );
		device.createRenderPipelineAsync.mockImplementation( () => {
			throw new Error( 'sync pipeline error' );
		} );
		const renderObject = {
			object: {},
			material: makeMaterial(),
			geometry: { index: null },
			pipeline,
			context: { textures: null, depth: false, stencil: false, sampleCount: 1 },
			getBindings: () => []
		};
		const promises = [];

		utils.createRenderPipeline( renderObject, promises );

		expect( promises ).toHaveLength( 1 );
		await Promise.all( promises );
		expect( data.get( pipeline ).error ).toBe( true );
		expect( errorSpy ).toHaveBeenCalledWith( expect.stringContaining( 'sync pipeline error' ) );
		errorSpy.mockRestore();
	} );

	it( 'creates a render bundle encoder from the current render-context state', () => {
		const { utils, backend, device, created } = createBackend();
		const renderContext = { textures: null, sampleCount: 4 };

		const encoder = utils.createBundleEncoder( renderContext, 'bundle-label' );

		expect( backend.utils.getCurrentDepthStencilFormat ).toHaveBeenCalledWith( renderContext );
		expect( backend.utils.getCurrentColorFormats ).toHaveBeenCalledWith( renderContext );
		expect( backend.utils.getSampleCountRenderContext ).toHaveBeenCalledWith( renderContext );
		expect( created.bundle ).toEqual( {
			label: 'bundle-label',
			colorFormats: [ 'bgra8unorm', 'rgba16float' ],
			depthStencilFormat: 'depth24plus',
			sampleCount: 4
		} );
		expect( encoder.kind ).toBe( 'bundleEncoder' );
	} );

	it( 'uses the default render bundle encoder label', () => {
		const { utils, created } = createBackend();
		utils.createBundleEncoder( { textures: [], sampleCount: 1 } );
		expect( created.bundle.label ).toBe( 'renderBundleEncoder' );
	} );

	it( 'creates a synchronous compute pipeline', async () => {
		const { utils, backend, device, data, created } = createBackend();
		const program = { stage: 'compute', name: 'kernel' };
		const pipeline = { computeProgram: program, id: 'computePipeline' };
		const programData = { module: { kind: 'computeModule' } };
		const bindGroup = { id: 'bindings' };
		const pipelineData = data.get( pipeline );
		data.set( program, programData );
		data.set( bindGroup, { layout: { layoutGPU: { kind: 'computeLayout' } } } );

		utils.createComputePipeline( pipeline, [ bindGroup ] );
		await Promise.resolve();

		expect( created.pipelineLayout.bindGroupLayouts ).toEqual( [ { kind: 'computeLayout' } ] );
		expect( created.compute ).toEqual( {
			label: 'computePipeline_compute_kernel',
			compute: programData.module,
			layout: created.pipelineLayout
		} );
		expect( pipelineData.pipeline ).toEqual( { kind: 'computePipeline', descriptor: created.compute } );
		expect( device.pushErrorScope ).toHaveBeenCalledWith( 'validation' );
	} );

	it( 'resolves async compute pipelines and records validation errors', async () => {
		const { utils, backend, device, data } = createBackend();
		const errorSpy = jest.spyOn( console, 'error' ).mockImplementation( () => {} );
		const program = { stage: 'compute', name: '', code: '' };
		const pipeline = { computeProgram: program };
		const pipelineData = data.get( pipeline );
		data.set( program, {
			module: { kind: 'computeModule', getCompilationInfo: async () => ( { messages: [] } ) }
		} );
		device.createComputePipelineAsync.mockResolvedValue( { kind: 'asyncCompute' } );
		device.popErrorScope.mockResolvedValue( { message: 'validation failed' } );
		const promises = [];

		utils.createComputePipeline( pipeline, [], promises );
		expect( promises ).toHaveLength( 1 );
		await Promise.all( promises );

		expect( pipelineData.pipeline ).toEqual( { kind: 'asyncCompute' } );
		expect( pipelineData.error ).toBe( true );
		expect( errorSpy ).toHaveBeenCalledWith( expect.stringContaining( 'validation failed' ) );
		errorSpy.mockRestore();
	} );

	it( 'computes normal, premultiplied and custom blending states', () => {
		const { utils } = createBackend();

		expect( utils._getBlending( {
			blending: NormalBlending, premultipliedAlpha: false
		} ) ).toEqual( {
			color: { srcFactor: GPUBlendFactor.SrcAlpha, dstFactor: GPUBlendFactor.OneMinusSrcAlpha, operation: GPUBlendOperation.Add },
			alpha: { srcFactor: GPUBlendFactor.One, dstFactor: GPUBlendFactor.OneMinusSrcAlpha, operation: GPUBlendOperation.Add }
		} );

		expect( utils._getBlending( {
			blending: NormalBlending, premultipliedAlpha: true
		} ) ).toEqual( {
			color: { srcFactor: GPUBlendFactor.One, dstFactor: GPUBlendFactor.OneMinusSrcAlpha, operation: GPUBlendOperation.Add },
			alpha: { srcFactor: GPUBlendFactor.One, dstFactor: GPUBlendFactor.OneMinusSrcAlpha, operation: GPUBlendOperation.Add }
		} );

		expect( utils._getBlending( {
			blending: CustomBlending,
			blendSrc: SrcColorFactor,
			blendDst: ZeroFactor,
			blendSrcAlpha: null,
			blendDstAlpha: OneFactor,
			blendEquation: SubtractEquation,
			blendEquationAlpha: ReverseSubtractEquation
		} ) ).toEqual( {
			color: { srcFactor: GPUBlendFactor.Src, dstFactor: GPUBlendFactor.Zero, operation: GPUBlendOperation.Subtract },
			alpha: { srcFactor: GPUBlendFactor.Src, dstFactor: GPUBlendFactor.One, operation: GPUBlendOperation.ReverseSubtract }
		} );
	} );

	it( 'maps every supported blend factor and operation', () => {
		const { utils } = createBackend();
		expect( utils._getBlendFactor( ZeroFactor ) ).toBe( GPUBlendFactor.Zero );
		expect( utils._getBlendFactor( OneFactor ) ).toBe( GPUBlendFactor.One );
		expect( utils._getBlendFactor( SrcColorFactor ) ).toBe( GPUBlendFactor.Src );
		expect( utils._getBlendFactor( OneMinusSrcColorFactor ) ).toBe( GPUBlendFactor.OneMinusSrc );
		expect( utils._getBlendFactor( SrcAlphaFactor ) ).toBe( GPUBlendFactor.SrcAlpha );
		expect( utils._getBlendFactor( OneMinusSrcAlphaFactor ) ).toBe( GPUBlendFactor.OneMinusSrcAlpha );
		expect( utils._getBlendFactor( OneMinusDstColorFactor ) ).toBe( GPUBlendFactor.OneMinusDst );
		expect( utils._getBlendFactor( OneMinusDstAlphaFactor ) ).toBe( GPUBlendFactor.OneMinusDstAlpha );
		expect( utils._getBlendFactor( SrcAlphaSaturateFactor ) ).toBe( GPUBlendFactor.SrcAlphaSaturated );
		expect( utils._getBlendFactor( ConstantColorFactor ) ).toBe( GPUBlendFactor.Constant );
		expect( utils._getBlendFactor( ConstantAlphaFactor ) ).toBe( GPUBlendFactor.Constant );
		expect( utils._getBlendFactor( OneMinusConstantColorFactor ) ).toBe( GPUBlendFactor.OneMinusConstant );
		expect( utils._getBlendFactor( OneMinusConstantAlphaFactor ) ).toBe( GPUBlendFactor.OneMinusConstant );

		expect( utils._getBlendOperation( AddEquation ) ).toBe( GPUBlendOperation.Add );
		expect( utils._getBlendOperation( SubtractEquation ) ).toBe( GPUBlendOperation.Subtract );
		expect( utils._getBlendOperation( ReverseSubtractEquation ) ).toBe( GPUBlendOperation.ReverseSubtract );
		expect( utils._getBlendOperation( MinEquation ) ).toBe( GPUBlendOperation.Min );
		expect( utils._getBlendOperation( MaxEquation ) ).toBe( GPUBlendOperation.Max );
	} );

	it( 'maps stencil comparison and operation values', () => {
		const { utils } = createBackend();
		expect( utils._getStencilCompare( { stencilFunc: NeverStencilFunc } ) ).toBe( GPUCompareFunction.Never );
		expect( utils._getStencilCompare( { stencilFunc: LessEqualStencilFunc } ) ).toBe( GPUCompareFunction.LessEqual );
		expect( utils._getStencilCompare( { stencilFunc: EqualStencilFunc } ) ).toBe( GPUCompareFunction.Equal );
		expect( utils._getStencilOperation( ZeroStencilOp ) ).toBe( GPUStencilOperation.Zero );
		expect( utils._getStencilOperation( InvertStencilOp ) ).toBe( GPUStencilOperation.Invert );
		expect( utils._getStencilOperation( IncrementWrapStencilOp ) ).toBe( GPUStencilOperation.IncrementWrap );
		expect( utils._getStencilOperation( DecrementWrapStencilOp ) ).toBe( GPUStencilOperation.DecrementWrap );
	} );

	it( 'derives primitive state from object side, culling and mirrored transforms', () => {
		const { utils } = createBackend();
		const geometry = { index: { array: new Uint16Array( [ 0, 1, 2 ] ) } };

		expect( utils._getPrimitiveState(
			{ isMesh: true, matrixWorld: { determinantAffine: () => 1 } },
			geometry,
			{ side: BackSide }
		) ).toMatchObject( {
			topology: GPUPrimitiveTopology.TriangleList,
			frontFace: GPUFrontFace.CW,
			cullMode: GPUCullMode.Back
		} );

		expect( utils._getPrimitiveState(
			{ isMesh: true, matrixWorld: { determinantAffine: () => 1 } },
			geometry,
			{ side: DoubleSide }
		).cullMode ).toBe( GPUCullMode.None );

		expect( utils._getPrimitiveState(
			{ isMesh: true, matrixWorld: { determinantAffine: () => -1 } },
			geometry,
			{ side: FrontSide }
		).frontFace ).toBe( GPUFrontFace.CW );
	} );

	it( 'maps color-write and depth-testing state', () => {
		const { utils, backend } = createBackend();
		expect( utils._getColorWriteMask( { colorWrite: true } ) ).toBe( GPUColorWriteFlags.All );
		expect( utils._getColorWriteMask( { colorWrite: false } ) ).toBe( GPUColorWriteFlags.None );

		expect( utils._getDepthCompare( { depthTest: false } ) ).toBe( GPUCompareFunction.Always );
		expect( utils._getDepthCompare( { depthTest: true, depthFunc: NeverDepth } ) ).toBe( GPUCompareFunction.Never );
		expect( utils._getDepthCompare( { depthTest: true, depthFunc: AlwaysDepth } ) ).toBe( GPUCompareFunction.Always );
		expect( utils._getDepthCompare( { depthTest: true, depthFunc: LessDepth } ) ).toBe( GPUCompareFunction.Less );
		expect( utils._getDepthCompare( { depthTest: true, depthFunc: EqualDepth } ) ).toBe( GPUCompareFunction.Equal );
		expect( utils._getDepthCompare( { depthTest: true, depthFunc: GreaterEqualDepth } ) ).toBe( GPUCompareFunction.GreaterEqual );
		expect( utils._getDepthCompare( { depthTest: true, depthFunc: GreaterDepth } ) ).toBe( GPUCompareFunction.Greater );

		backend.parameters.reversedDepthBuffer = true;
		expect( utils._getDepthCompare( { depthTest: true, depthFunc: LessDepth } ) ).toBe( GPUCompareFunction.Greater );
		expect( utils._getDepthCompare( { depthTest: true, depthFunc: LessEqualDepth } ) ).toBe( GPUCompareFunction.GreaterEqual );
	} );

