import { afterAll, beforeAll, describe, expect, it, jest } from '@jest/globals';
import WebGPUTimestampQueryPool from '../../../../src/renderers/webgpu/utils/WebGPUTimestampQueryPool.js';

const usage = {
	MAP_READ: 1,
	COPY_SRC: 4,
	COPY_DST: 8,
	QUERY_RESOLVE: 512
};

function createDevice() {
	const submitted = [];
	const commandEncoders = [];
	const device = {
		createQuerySet: jest.fn( ( descriptor ) => ( {
			kind: 'querySet',
			label: descriptor.label,
			type: descriptor.type,
			count: descriptor.count,
			destroy: jest.fn()
		} ) ),
		createBuffer: jest.fn( ( descriptor ) => ( {
			kind: 'buffer',
			label: descriptor.label,
			size: descriptor.size,
			usage: descriptor.usage,
			mapState: 'unmapped',
			mapAsync: jest.fn( async () => {} ),
			getMappedRange: jest.fn( () => new ArrayBuffer( descriptor.size ) ),
			unmap: jest.fn(),
			destroy: jest.fn()
		} ) ),
		createCommandEncoder: jest.fn( ( descriptor ) => {
			const encoder = {
				label: descriptor.label,
				resolveQuerySet: jest.fn(),
				copyBufferToBuffer: jest.fn(),
				finish: jest.fn( () => ( { kind: 'commandBuffer' } ) )
			};
			commandEncoders.push( encoder );
			return encoder;
		} ),
		queue: {
			submit: jest.fn( ( commands ) => submitted.push( [ ...commands ] ) )
		}
	};
	return { device, submitted, commandEncoders };
}

function makePool( maxQueries = 8 ) {
	const { device, submitted, commandEncoders } = createDevice();
	const pool = new WebGPUTimestampQueryPool( device, 'render', maxQueries );
	return { pool, device, submitted, commandEncoders };
}

function setTimestampData( buffer, values ) {
	const data = new BigUint64Array( values.length );
	for ( let i = 0; i < values.length; i ++ ) data[ i ] = BigInt( values[ i ] );
	const bytes = new Uint8Array( data.buffer );
	new Uint8Array( buffer.getMappedRange() ).set( bytes );
}

describe( 'WebGPUTimestampQueryPool', () => {

	beforeAll( () => {
		globalThis.GPUBufferUsage = usage;
		globalThis.GPUMapMode = { READ: 1, WRITE: 2 };
	} );

	afterAll( () => {
		delete globalThis.GPUBufferUsage;
		delete globalThis.GPUMapMode;
	} );

	it( 'creates the query set and resolve/result buffers with aligned sizes and usages', () => {
		const { pool, device, commandEncoders } = makePool( 16 );

		expect( device.createQuerySet ).toHaveBeenCalledWith( expect.objectContaining( {
			label: 'queryset_global_timestamp_render',
			type: 'timestamp',
			count: 16
		} ) );
		expect( pool.querySet ).toMatchObject( { kind: 'querySet', count: 16 } );
		expect( device.createBuffer ).toHaveBeenCalledTimes( 2 );
		expect( pool.resolveBuffer ).toMatchObject( {
			kind: 'buffer',
			label: 'buffer_timestamp_resolve_render',
			size: 128,
			usage: usage.QUERY_RESOLVE | usage.COPY_SRC
		} );
		expect( pool.resultBuffer ).toMatchObject( {
			kind: 'buffer',
			label: 'buffer_timestamp_result_render',
			size: 128,
			usage: usage.COPY_DST | usage.MAP_READ
		} );
		expect( commandEncoders ).toHaveLength( 0 );
	} );

	it( 'allocates a pair of query offsets per context', () => {
		const { pool } = makePool( 8 );

		expect( pool.allocateQueriesForContext( 'camera:f1' ) ).toBe( 0 );
		expect( pool.allocateQueriesForContext( 'shadow:f1' ) ).toBe( 2 );
		expect( pool.currentQueryIndex ).toBe( 4 );
		expect( pool.queryOffsets ).toEqual( new Map( [ [ 'camera:f1', 0 ], [ 'shadow:f1', 2 ] ] ) );
	} );

	it( 'does not allocate when timestamp tracking is disabled or disposed', () => {
		const { pool } = makePool( 8 );
		pool.trackTimestamp = false;
		expect( pool.allocateQueriesForContext( 'camera:f1' ) ).toBeNull();
		pool.trackTimestamp = true;
		pool.isDisposed = true;
		expect( pool.allocateQueriesForContext( 'camera:f1' ) ).toBeNull();
	} );

	it( 'resolves outstanding work before wrapping the query ring', () => {
		const { pool } = makePool( 4 );
		jest.spyOn( pool, 'resolveQueriesAsync' ).mockResolvedValue( 3 );
		pool.currentQueryIndex = 4;
		pool.queryOffsets.set( 'old:f1', 0 );

		expect( pool.allocateQueriesForContext( 'new:f2' ) ).toBe( 0 );
		expect( pool.resolveQueriesAsync ).toHaveBeenCalledTimes( 1 );
		expect( pool.currentQueryIndex ).toBe( 2 );
		expect( pool.queryOffsets ).toEqual( new Map( [ [ 'new:f2', 0 ] ] ) );
	} );

	it( 'returns the last value immediately when there is no work to resolve', async () => {
		const { pool } = makePool( 8 );
		pool.lastValue = 12.5;

		expect( await pool.resolveQueriesAsync() ).toBe( 12.5 );
		pool.trackTimestamp = false;
		expect( await pool.resolveQueriesAsync() ).toBe( 12.5 );
		pool.trackTimestamp = true;
		pool.isDisposed = true;
		expect( await pool.resolveQueriesAsync() ).toBe( 12.5 );
	} );

	it( 'shares an in-flight resolve operation', async () => {
		const { pool } = makePool( 8 );
		let finish;
		pool.currentQueryIndex = 2;
		pool.queryOffsets.set( 'camera:f1', 0 );
		jest.spyOn( pool, '_resolveQueries' ).mockImplementation( () => new Promise( ( resolve ) => {
			finish = resolve;
		} ) );

		const first = pool.resolveQueriesAsync();
		const second = pool.resolveQueriesAsync();
		expect( pool._resolveQueries ).toHaveBeenCalledTimes( 1 );
		finish( 7 );
		await expect( first ).resolves.toBe( 7 );
		await expect( second ).resolves.toBe( 7 );
		expect( pool.pendingResolve ).toBeNull();
	} );

	it( 'resolves query timestamps and returns the last frame duration in milliseconds', async () => {
		const { pool, device, submitted, commandEncoders } = makePool( 8 );
		const resultBuffer = pool.resultBuffer;
		setTimestampData( resultBuffer, [
			0, 1_000_000,
			0, 2_500_000
		] );
		pool.currentQueryIndex = 4;
		pool.queryOffsets.set( 'camera:f1', 0 );
		pool.queryOffsets.set( 'shadow:f1', 2 );
		pool.queryOffsets.set( 'camera:f2', 0 );
		pool.queryOffsets.set( 'shadow:f2', 2 );

		const duration = await pool._resolveQueries();

		expect( duration ).toBe( 3.5 );
		expect( pool.lastValue ).toBe( 3.5 );
		expect( pool.frames ).toEqual( [ 1, 2 ] );
		expect( pool.timestamps.get( 'camera:f1' ) ).toBe( 1 );
		expect( pool.timestamps.get( 'shadow:f1' ) ).toBe( 2.5 );
		expect( pool.currentQueryIndex ).toBe( 0 );
		expect( pool.queryOffsets.size ).toBe( 0 );
		expect( commandEncoders ).toHaveLength( 1 );
		expect( commandEncoders[ 0 ].resolveQuerySet ).toHaveBeenCalledWith(
			pool.querySet, 0, 4, pool.resolveBuffer, 0
		);
		expect( commandEncoders[ 0 ].copyBufferToBuffer ).toHaveBeenCalledWith(
			pool.resolveBuffer, 0, resultBuffer, 0, 32
		);
		expect( submitted ).toEqual( [ [ { kind: 'commandBuffer' } ] ] );
		expect( resultBuffer.mapAsync ).toHaveBeenCalledWith( 1, 0, 32 );
		expect( resultBuffer.unmap ).toHaveBeenCalled();
	} );

	it( 'does not map while the result buffer is already mapped', async () => {
		const { pool, commandEncoders } = makePool( 8 );
		pool.lastValue = 4;
		pool.currentQueryIndex = 2;
		pool.queryOffsets.set( 'camera:f1', 0 );
		pool.resultBuffer.mapState = 'mapped';

		await expect( pool._resolveQueries() ).resolves.toBe( 4 );
		expect( commandEncoders ).toHaveLength( 0 );
		expect( pool.resultBuffer.mapAsync ).not.toHaveBeenCalled();
	} );

	it( 'logs and preserves the last value when query resolution fails', async () => {
		const { pool } = makePool( 8 );
		const errorSpy = jest.spyOn( console, 'error' ).mockImplementation( () => {} );
		pool.lastValue = 9;
		pool.currentQueryIndex = 2;
		pool.queryOffsets.set( 'camera:f1', 0 );
		pool.resultBuffer.mapAsync.mockRejectedValue( new Error( 'map failed' ) );

		await expect( pool._resolveQueries() ).resolves.toBe( 9 );
		expect( errorSpy ).toHaveBeenCalledWith( expect.stringContaining( 'Error resolving queries:' ), expect.any( Error ) );
		errorSpy.mockRestore();
	} );

	it( 'throws when resolving a malformed context id and returns the last value', async () => {
		const { pool } = makePool( 8 );
		const errorSpy = jest.spyOn( console, 'error' ).mockImplementation( () => {} );
		pool.lastValue = 5;
		pool.currentQueryIndex = 2;
		pool.queryOffsets.set( 'not-a-frame-id', 0 );

		await expect( pool._resolveQueries() ).resolves.toBe( 5 );
		expect( errorSpy ).toHaveBeenCalled();
		expect( pool.resultBuffer.unmap ).toHaveBeenCalled();
		errorSpy.mockRestore();
	} );

	it( 'disposes pending work, unmaps buffers and is idempotent', async () => {
		const { pool } = makePool( 8 );
		const querySet = pool.querySet;
		const resolveBuffer = pool.resolveBuffer;
		const resultBuffer = pool.resultBuffer;
		resultBuffer.mapState = 'mapped';
		let finishPending;
		pool.pendingResolve = new Promise( ( resolve ) => { finishPending = resolve; } );
		pool.queryOffsets.set( 'camera:f1', 0 );
		pool.timestamps.set( 'camera:f1', 1 );
		pool.frames = [ 1 ];

		const disposePromise = pool.dispose();
		finishPending();
		await disposePromise;

		expect( pool.isDisposed ).toBe( true );
		expect( resultBuffer.unmap ).toHaveBeenCalled();
		expect( querySet.destroy ).toHaveBeenCalled();
		expect( resolveBuffer.destroy ).toHaveBeenCalled();
		expect( resultBuffer.destroy ).toHaveBeenCalled();
		expect( pool.querySet ).toBeNull();
		expect( pool.resolveBuffer ).toBeNull();
		expect( pool.resultBuffer ).toBeNull();
		expect( pool.queryOffsets.size ).toBe( 0 );
		expect( pool.timestamps.size ).toBe( 0 );
		expect( pool.frames ).toEqual( [] );

		querySet.destroy.mockClear();
		await pool.dispose();
		expect( querySet.destroy ).not.toHaveBeenCalled();
	} );

	it( 'continues disposal when a pending resolve rejects', async () => {
		const { pool } = makePool( 8 );
		const errorSpy = jest.spyOn( console, 'error' ).mockImplementation( () => {} );
		const querySet = pool.querySet;
		pool.pendingResolve = Promise.reject( new Error( 'pending failed' ) );

		await pool.dispose();

		expect( errorSpy ).toHaveBeenCalledWith( expect.stringContaining( 'Error waiting for pending resolve:' ), expect.any( Error ) );
		expect( querySet.destroy ).toHaveBeenCalled();
		errorSpy.mockRestore();
	} );

} );
