				[ new Int16Array( 2 ), gl.SHORT ],
				[ new Uint32Array( 2 ), gl.UNSIGNED_INT ],
				[ new Int32Array( 2 ), gl.INT ],
				[ new Int8Array( 2 ), gl.BYTE ],
				[ new Uint8Array( 2 ), gl.UNSIGNED_BYTE ],
