			for ( const [ array, expectedType ] of cases ) {

				const attribute = createAttribute( array, 1 );
				utils.createAttribute( attribute, gl.ARRAY_BUFFER );

				expect( backend.get( attribute ).type ).toBe( expectedType );

			}

		} );

