			utils.createAttribute( attribute, gl.ARRAY_BUFFER );

			const attributeData = backend.get( attribute );

			expect( gl.createBuffer ).toHaveBeenCalledTimes( 2 );
			expect( attributeData.buffers ).toHaveLength( 2 );
			expect( attributeData.activeBufferIndex ).toBe( 0 );
			expect( attributeData.bufferGPU ).toBe( attributeData.buffers[ 0 ] );
			expect( attributeData.transformBuffer ).toBe( attributeData.buffers[ 1 ] );

			attributeData.switchBuffers();

			expect( attributeData.activeBufferIndex ).toBe( 1 );
			expect( attributeData.bufferGPU ).toBe( attributeData.buffers[ 1 ] );
			expect( attributeData.transformBuffer ).toBe( attributeData.buffers[ 0 ] );

		} );

		it( 'allocates a second buffer for storage instanced buffer attributes', () => {

			const attribute = createAttribute( new Float32Array( 4 ), 1, { isStorageInstancedBufferAttribute: true } );

			utils.createAttribute( attribute, gl.ARRAY_BUFFER );

			expect( gl.createBuffer ).toHaveBeenCalledTimes( 2 );
			expect( backend.get( attribute ).buffers ).toHaveLength( 2 );

		} );

		it( 'stores the data for the underlying interleaved buffer', () => {

			const data = { array: new Float32Array( 8 ), version: 2, BYTES_PER_ELEMENT: 4, updateRanges: [], addEventListener() {} };
			const attribute = {
				isInterleavedBufferAttribute: true,
				data,
				offset: 1,
				itemSize: 2,
				pbo: undefined
			};

			// The backend resolves interleaved attributes to their buffer
			backend.getBufferAttribute = ( attribute ) => attribute.isInterleavedBufferAttribute ? attribute.data : attribute;

			utils.createAttribute( attribute, gl.ARRAY_BUFFER );

			expect( backend.data.has( data ) ).toBe( true );
			expect( backend.get( data ).bufferGPU ).toBeDefined();

		} );

	} );

