		it( 're-uploads the whole array when no update ranges are defined', () => {

			const array = new Float32Array( [ 1, 2, 3, 4 ] );
			const attribute = createAttribute( array, 2 );

			utils.createAttribute( attribute, gl.ARRAY_BUFFER );
			gl.bufferSubData.mockClear();
			gl.bindBuffer.mockClear();

