			utils.updateAttribute( attribute );

			expect( gl.bindBuffer ).toHaveBeenNthCalledWith( 1, gl.ARRAY_BUFFER, backend.get( attribute ).bufferGPU );
			expect( gl.bufferSubData ).toHaveBeenCalledWith( gl.ARRAY_BUFFER, 0, array );
			expect( gl.bindBuffer ).toHaveBeenLastCalledWith( gl.ARRAY_BUFFER, null );
			expect( backend.get( attribute ).version ).toBe( 3 );

		} );

		it( 'uploads only the requested update ranges and clears them', () => {

			const array = new Float32Array( 16 );
			const attribute = createAttribute( array, 4 );

			utils.createAttribute( attribute, gl.ARRAY_BUFFER );
			gl.bufferSubData.mockClear();

			attribute.addUpdateRange( 2, 4 );
			attribute.addUpdateRange( 8, 4 );

			const clearUpdateRanges = jest.spyOn( attribute, 'clearUpdateRanges' );

			utils.updateAttribute( attribute );

