			expect( gl.bufferSubData ).toHaveBeenNthCalledWith( 1, gl.ARRAY_BUFFER, 2 * 4, array, 2, 4 );
			expect( gl.bufferSubData ).toHaveBeenNthCalledWith( 2, gl.ARRAY_BUFFER, 8 * 4, array, 8, 4 );
			expect( clearUpdateRanges ).toHaveBeenCalledTimes( 1 );
			expect( attribute.updateRanges ).toHaveLength( 0 );

		} );

	} );

	describe( 'destroyAttribute()', () => {

		it( 'deletes the GPU buffer and the backend data', () => {

			const attribute = createAttribute( new Float32Array( 4 ), 1 );
			utils.createAttribute( attribute, gl.ARRAY_BUFFER );

			const bufferGPU = backend.get( attribute ).bufferGPU;
			utils.destroyAttribute( attribute );

			expect( gl.deleteBuffer ).toHaveBeenCalledWith( bufferGPU );
			expect( backend.data.has( attribute ) ).toBe( false );

		} );

		it( 'deletes both buffers of a storage buffer attribute', () => {

			const attribute = createAttribute( new Float32Array( 4 ), 1, { isStorageBufferAttribute: true } );
			utils.createAttribute( attribute, gl.ARRAY_BUFFER );

			const { buffers } = backend.get( attribute );
			utils.destroyAttribute( attribute );

			expect( gl.deleteBuffer ).toHaveBeenCalledTimes( 2 );
			expect( gl.deleteBuffer ).toHaveBeenNthCalledWith( 1, buffers[ 0 ] );
			expect( gl.deleteBuffer ).toHaveBeenNthCalledWith( 2, buffers[ 1 ] );

		} );

	} );

	describe( 'getArrayBufferAsync()', () => {

		it( 'reads the full buffer into a new ArrayBuffer', async () => {

			const attribute = createAttribute( new Float32Array( [ 1, 2, 3, 4 ] ), 1, { isStorageBufferAttribute: true } );
			utils.createAttribute( attribute, gl.ARRAY_BUFFER );

			const bufferGPU = backend.get( attribute ).bufferGPU;
			const result = await utils.getArrayBufferAsync( attribute );

			expect( result ).toBeInstanceOf( ArrayBuffer );
			expect( result.byteLength ).toBe( 16 );
			expect( gl.bindBuffer ).toHaveBeenCalledWith( gl.COPY_READ_BUFFER, bufferGPU );
			expect( gl.getBufferSubData ).toHaveBeenCalledWith( gl.COPY_READ_BUFFER, 0, expect.any( Uint8Array ) );
			expect( gl.bindBuffer ).toHaveBeenLastCalledWith( gl.COPY_WRITE_BUFFER, null );

