			utils.createAttribute( attribute, gl.ARRAY_BUFFER );

			const result = await utils.getArrayBufferAsync( attribute, null, 4, 8 );

			expect( result.byteLength ).toBe( 8 );
			expect( gl.getBufferSubData ).toHaveBeenCalledWith( gl.COPY_READ_BUFFER, 4, expect.any( Uint8Array ) );

		} );

		it( 'writes into a caller provided ArrayBuffer', async () => {

			const attribute = createAttribute( new Float32Array( 4 ), 1, { isStorageBufferAttribute: true } );
			utils.createAttribute( attribute, gl.ARRAY_BUFFER );

