import WebGLState from '../../../../src/renderers/webgl-fallback/utils/WebGLState.js';
import { setConsoleFunction } from '../../../../src/utils.js';
import { Material } from '../../../../src/materials/Material.js';
import { Color } from '../../../../src/math/Color.js';
import {
	CullFaceNone, CullFaceBack, CullFaceFront, DoubleSide, BackSide, FrontSide,
	NormalBlending, NoBlending, CustomBlending, AdditiveBlending, SubtractiveBlending,
	MultiplyBlending, AddEquation, SubtractEquation, ReverseSubtractEquation, MinEquation, MaxEquation,
	ZeroFactor, OneFactor, SrcColorFactor, SrcAlphaFactor, DstColorFactor, OneMinusSrcAlphaFactor,
	OneMinusDstColorFactor, ConstantColorFactor, OneMinusConstantAlphaFactor,
	NeverDepth, AlwaysDepth, LessDepth, LessEqualDepth, EqualDepth, GreaterEqualDepth,
	GreaterDepth, NotEqualDepth, ReversedDepthFuncs, MaterialBlending
} from '../../../../src/constants.js';
import { ReversedDepthFuncs as ReverseFuncs } from '../../../../src/utils.js';
import { createMockBackend, createMockGL } from './mockWebGL.js';

const clipControlExt = {
	LOWER_LEFT_EXT: 0x8CA1,
	ZERO_TO_ONE_EXT: 0x8CA2,
	NEGATIVE_ONE_TO_ONE_EXT: 0x8CA3,
	clipControlEXT: ( ...args ) => args
};

describe( 'WebGLState', () => {

	let backend, gl, state, messages;

	beforeEach( () => {

		messages = [];
		setConsoleFunction( ( type, message, ...params ) => messages.push( { type, message, params } ) );

		backend = createMockBackend( {
			glOptions: { extensions: { EXT_clip_control: clipControlExt } },
			renderer: { reversedDepthBuffer: false, currentSamples: 0 }
		} );
		gl = backend.gl;
		state = backend.state;

	} );

	afterEach( () => {

		setConsoleFunction( null );

	} );

	function createMaterial( properties = {} ) {

		return Object.assign( new Material(), properties );

	}

	describe( 'constructor', () => {

		it( 'reads the initial viewport, scissor box and texture unit count', () => {

			expect( state.backend ).toBe( backend );
			expect( state.gl ).toBe( gl );
			expect( gl.getParameter ).toHaveBeenCalledWith( gl.MAX_TEXTURE_IMAGE_UNITS );
			expect( gl.getParameter ).toHaveBeenCalledWith( gl.SCISSOR_BOX );
			expect( gl.getParameter ).toHaveBeenCalledWith( gl.VIEWPORT );
			expect( state.maxTextures ).toBe( 16 );
			expect( state.currentScissor.toArray() ).toEqual( [ 0, 0, 300, 150 ] );
			expect( state.currentViewport.toArray() ).toEqual( [ 0, 0, 300, 150 ] );

		} );

		it( 'starts with an empty state cache', () => {

			expect( state.enabled ).toEqual( {} );
			expect( state.parameters ).toEqual( {} );
			expect( state.currentProgram ).toBeNull();
			expect( state.currentTextureSlot ).toBeNull();
			expect( state.currentVAO ).toBeNull();
			expect( state.currentIndex ).toBeNull();
			expect( state.currentBlendingEnabled ).toBe( false );

		} );

	} );

	describe( 'enable() / disable()', () => {

		it( 'only forwards state changes to the context', () => {

			state.enable( gl.CULL_FACE );
			state.enable( gl.CULL_FACE );
			state.disable( gl.CULL_FACE );
			state.disable( gl.CULL_FACE );

			expect( gl.enable ).toHaveBeenCalledTimes( 1 );
			expect( gl.enable ).toHaveBeenCalledWith( gl.CULL_FACE );
			expect( gl.disable ).toHaveBeenCalledTimes( 1 );
			expect( gl.disable ).toHaveBeenCalledWith( gl.CULL_FACE );
			expect( state.enabled[ gl.CULL_FACE ] ).toBe( false );

		} );

	} );

	describe( 'setFlipSided()', () => {

		it( 'maps the winding order and caches it', () => {

			state.setFlipSided( true );
			expect( gl.frontFace ).toHaveBeenCalledWith( gl.CW );

			state.setFlipSided( true );
			expect( gl.frontFace ).toHaveBeenCalledTimes( 1 );

			state.setFlipSided( false );
			expect( gl.frontFace ).toHaveBeenLastCalledWith( gl.CCW );
			expect( gl.frontFace ).toHaveBeenCalledTimes( 2 );

		} );

	} );

	describe( 'setCullFace()', () => {

		it( 'enables culling for back and front faces', () => {

			state.setCullFace( CullFaceBack );
			expect( gl.enable ).toHaveBeenCalledWith( gl.CULL_FACE );
			expect( gl.cullFace ).toHaveBeenCalledWith( gl.BACK );

			state.setCullFace( CullFaceFront );
			expect( gl.cullFace ).toHaveBeenCalledWith( gl.FRONT );

			expect( state.currentCullFace ).toBe( CullFaceFront );

		} );

		it( 'disables culling for CullFaceNone', () => {

			state.setCullFace( CullFaceNone );

			expect( gl.disable ).toHaveBeenCalledWith( gl.CULL_FACE );
			expect( gl.cullFace ).not.toHaveBeenCalled();
			expect( state.currentCullFace ).toBe( CullFaceNone );

		} );

		it( 'falls back to FRONT_AND_BACK for other cull face modes', () => {

			state.setCullFace( undefined );

			expect( gl.cullFace ).toHaveBeenCalledWith( gl.FRONT_AND_BACK );

		} );

	} );

	describe( 'setLineWidth()', () => {

		it( 'only forwards changed line widths', () => {

			state.setLineWidth( 2 );
			state.setLineWidth( 2 );
			state.setLineWidth( 1 );

			expect( gl.lineWidth ).toHaveBeenCalledTimes( 2 );
			expect( gl.lineWidth ).toHaveBeenNthCalledWith( 1, 2 );
			expect( gl.lineWidth ).toHaveBeenNthCalledWith( 2, 1 );

		} );

	} );

	describe( 'setBlending()', () => {

		it( 'does nothing for NoBlending when blending was never enabled', () => {

			state.setBlending( NoBlending );

			expect( gl.disable ).not.toHaveBeenCalled();
			expect( gl.enable ).not.toHaveBeenCalled();
			expect( state.currentBlendingEnabled ).toBe( false );

		} );

		it( 'disables blending again after it has been enabled', () => {

			state.setBlending( NormalBlending );
			expect( gl.enable ).toHaveBeenCalledWith( gl.BLEND );

			state.setBlending( NoBlending );

			expect( gl.disable ).toHaveBeenCalledWith( gl.BLEND );
			expect( state.currentBlendingEnabled ).toBe( false );

		} );

		it( 'configures NormalBlending without premultiplied alpha', () => {

			state.setBlending( NormalBlending );

			expect( gl.blendEquation ).toHaveBeenCalledWith( gl.FUNC_ADD );
			expect( gl.blendFuncSeparate ).toHaveBeenCalledWith( gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA );
			expect( state.currentBlending ).toBe( NormalBlending );
			expect( state.currentPremultipledAlpha ).toBe( false );

		} );

		it( 'configures NormalBlending with premultiplied alpha', () => {

			state.setBlending( NormalBlending, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, true );

			expect( gl.blendFuncSeparate ).toHaveBeenCalledWith( gl.ONE, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA );
			expect( state.currentPremultipledAlpha ).toBe( true );

		} );

		it( 'uses a single blend function for premultiplied additive blending', () => {

			state.setBlending( AdditiveBlending, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, true );

			expect( gl.blendFunc ).toHaveBeenCalledWith( gl.ONE, gl.ONE );

		} );

		it( 'uses separate blend functions for additive blending', () => {

			state.setBlending( AdditiveBlending );

			expect( gl.blendFuncSeparate ).toHaveBeenCalledWith( gl.SRC_ALPHA, gl.ONE, gl.ONE, gl.ONE );

		} );

		it( 'reports subtractive and multiply blending without premultiplied alpha', () => {

			state.setBlending( SubtractiveBlending );
			state.setBlending( MultiplyBlending );

			expect( messages.filter( ( m ) => m.type === 'error' ) ).toHaveLength( 2 );
			expect( messages[ 0 ].message ).toContain( 'SubtractiveBlending requires material.premultipliedAlpha = true' );
			expect( messages[ 1 ].message ).toContain( 'MultiplyBlending requires material.premultipliedAlpha = true' );

		} );

		it( 'reports an invalid blending mode', () => {

			state.setBlending( 12345 );

			expect( messages ).toHaveLength( 1 );
			expect( messages[ 0 ].type ).toBe( 'error' );
			expect( messages[ 0 ].message ).toContain( 'Invalid blending' );

		} );

		it( 'skips redundant blend function updates', () => {

			state.setBlending( NormalBlending );
			gl.blendFuncSeparate.mockClear();
			gl.blendEquation.mockClear();

			state.setBlending( NormalBlending );

			expect( gl.blendFuncSeparate ).not.toHaveBeenCalled();
			expect( gl.blendEquation ).not.toHaveBeenCalled();

		} );

		it( 're-applies the blend function when premultiplied alpha changes', () => {

			state.setBlending( NormalBlending );
			gl.blendFuncSeparate.mockClear();

			state.setBlending( NormalBlending, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, true );

			expect( gl.blendFuncSeparate ).toHaveBeenCalledTimes( 1 );

		} );

		it( 'configures custom blending including alpha fallbacks', () => {

			const blendColor = new Color( 0.25, 0.5, 0.75 );

			state.setBlending(
				CustomBlending,
				SubtractEquation,
				SrcAlphaFactor,
				OneMinusSrcAlphaFactor,
				undefined,
				undefined,
				undefined,
				blendColor,
				0.5
			);

			expect( gl.blendEquationSeparate ).toHaveBeenCalledWith( gl.FUNC_SUBTRACT, gl.FUNC_SUBTRACT );
			expect( gl.blendFuncSeparate ).toHaveBeenCalledWith( gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA, gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA );
			expect( gl.blendColor ).toHaveBeenCalledWith( 0.25, 0.5, 0.75, 0.5 );

			expect( state.currentBlendEquation ).toBe( SubtractEquation );
			expect( state.currentBlendEquationAlpha ).toBe( SubtractEquation );
			expect( state.currentBlendSrcAlpha ).toBe( SrcAlphaFactor );
			expect( state.currentBlendDstAlpha ).toBe( OneMinusSrcAlphaFactor );
			expect( state.currentBlendColor.equals( blendColor ) ).toBe( true );
			expect( state.currentBlendAlpha ).toBe( 0.5 );

		} );

		it( 'maps custom blend equations and factors to WebGL constants', () => {

			state.setBlending(
				CustomBlending,
				MinEquation,
				ZeroFactor,
				DstColorFactor,
				MaxEquation,
				ConstantColorFactor,
				OneMinusConstantAlphaFactor,
				new Color( 0, 0, 0 ),
				0
			);

			expect( gl.blendEquationSeparate ).toHaveBeenCalledWith( gl.MIN, gl.MAX );
			expect( gl.blendFuncSeparate ).toHaveBeenCalledWith( gl.ZERO, gl.DST_COLOR, gl.CONSTANT_COLOR, gl.ONE_MINUS_CONSTANT_ALPHA );

		} );

		it( 'only updates the custom blend color when it changed', () => {

			const blendColor = new Color( 1, 0, 0 );

			state.setBlending( CustomBlending, AddEquation, OneFactor, ZeroFactor, undefined, undefined, undefined, blendColor, 1 );
			gl.blendColor.mockClear();

			state.setBlending( CustomBlending, AddEquation, OneFactor, ZeroFactor, undefined, undefined, undefined, new Color( 1, 0, 0 ), 1 );

			expect( gl.blendColor ).not.toHaveBeenCalled();

			state.setBlending( CustomBlending, AddEquation, OneFactor, ZeroFactor, undefined, undefined, undefined, new Color( 0, 1, 0 ), 1 );

			expect( gl.blendColor ).toHaveBeenCalledWith( 0, 1, 0, 1 );

		} );

	} );

	describe( 'color and depth state', () => {

		it( 'caches the color mask', () => {

			state.setColorMask( true );
			state.setColorMask( true );
			state.setColorMask( false );

			expect( gl.colorMask ).toHaveBeenCalledTimes( 2 );
			expect( gl.colorMask ).toHaveBeenNthCalledWith( 1, true, true, true, true );
			expect( gl.colorMask ).toHaveBeenNthCalledWith( 2, false, false, false, false );

		} );

		it( 'toggles the depth test', () => {

			state.setDepthTest( true );
			state.setDepthTest( true );
			state.setDepthTest( false );

			expect( gl.enable ).toHaveBeenCalledTimes( 1 );
			expect( gl.disable ).toHaveBeenCalledTimes( 1 );
			expect( gl.enable ).toHaveBeenCalledWith( gl.DEPTH_TEST );

		} );

		it( 'caches the depth mask', () => {

			state.setDepthMask( false );
			state.setDepthMask( false );
			state.setDepthMask( true );

			expect( gl.depthMask ).toHaveBeenCalledTimes( 2 );
			expect( gl.depthMask ).toHaveBeenNthCalledWith( 1, false );
			expect( gl.depthMask ).toHaveBeenNthCalledWith( 2, true );

		} );

		it( 'maps every three.js depth function', () => {

			const cases = [
				[ NeverDepth, gl.NEVER ],
				[ AlwaysDepth, gl.ALWAYS ],
				[ LessDepth, gl.LESS ],
				[ LessEqualDepth, gl.LEQUAL ],
				[ EqualDepth, gl.EQUAL ],
				[ GreaterEqualDepth, gl.GEQUAL ],
				[ GreaterDepth, gl.GREATER ],
				[ NotEqualDepth, gl.NOTEQUAL ]
			];

			for ( const [ input, expected ] of cases ) {

				state.setDepthFunc( input );
				expect( gl.depthFunc ).toHaveBeenLastCalledWith( expected );

			}

			expect( gl.depthFunc ).toHaveBeenCalledTimes( cases.length );

		} );

		it( 'falls back to LEQUAL for unknown depth functions', () => {

			state.setDepthFunc( 42 );

			expect( gl.depthFunc ).toHaveBeenCalledWith( gl.LEQUAL );

		} );

		it( 'skips redundant depth function changes', () => {

			state.setDepthFunc( LessDepth );
			state.setDepthFunc( LessDepth );

			expect( gl.depthFunc ).toHaveBeenCalledTimes( 1 );

		} );

		it( 'maps depth functions to their reversed counterparts', () => {

			state.setReversedDepth( true );
			gl.depthFunc.mockClear();

			state.setDepthFunc( LessDepth );
			expect( gl.depthFunc ).toHaveBeenLastCalledWith( gl.GREATER );
			expect( state.currentDepthFunc ).toBe( ReversedDepthFuncs[ LessDepth ] );

			state.setDepthFunc( GreaterEqualDepth );
			expect( gl.depthFunc ).toHaveBeenLastCalledWith( gl.LEQUAL );

		} );

	} );

	describe( 'setReversedDepth()', () => {

		it( 'configures the clip control extension and caches the state', () => {

			state.setReversedDepth( true );

			expect( clipControlExt.clipControlEXT ).toBeDefined();
			expect( state.currentDepthReversed ).toBe( true );

			const calls = gl.mock ? [] : [];
			expect( calls ).toHaveLength( 0 );

		} );

		it( 'only toggles the clip control when the mode changes', () => {

			const spy = jest.spyOn( clipControlExt, 'clipControlEXT' );

			state.setReversedDepth( true );
			state.setReversedDepth( true );
			expect( spy ).toHaveBeenCalledTimes( 1 );
			expect( spy ).toHaveBeenCalledWith( clipControlExt.LOWER_LEFT_EXT, clipControlExt.ZERO_TO_ONE_EXT );

			state.setReversedDepth( false );
			expect( spy ).toHaveBeenCalledTimes( 2 );
			expect( spy ).toHaveBeenLastCalledWith( clipControlExt.LOWER_LEFT_EXT, clipControlExt.NEGATIVE_ONE_TO_ONE_EXT );
			expect( state.currentDepthReversed ).toBe( false );

			spy.mockRestore();

		} );

	} );

	describe( 'viewport and scissor', () => {

		it( 'only forwards changed viewports', () => {

			state.viewport( 0, 0, 100, 100 );
			state.viewport( 0, 0, 100, 100 );

			expect( gl.viewport ).toHaveBeenCalledTimes( 1 );
			expect( gl.viewport ).toHaveBeenCalledWith( 0, 0, 100, 100 );
			expect( state.currentViewport.toArray() ).toEqual( [ 0, 0, 100, 100 ] );

		} );

		it( 'only forwards changed scissor boxes', () => {

			state.scissor( 1, 2, 3, 4 );
			state.scissor( 1, 2, 3, 4 );

			expect( gl.scissor ).toHaveBeenCalledTimes( 1 );
			expect( gl.scissor ).toHaveBeenCalledWith( 1, 2, 3, 4 );

		} );

		it( 'does not forward the initial viewport again', () => {

			state.viewport( 0, 0, 300, 150 );

			expect( gl.viewport ).not.toHaveBeenCalled();

		} );

	} );

	describe( 'stencil state', () => {

		it( 'enables and disables the tests', () => {

			state.setScissorTest( true );
			state.setScissorTest( true );
			state.setScissorTest( false );

			expect( gl.enable ).toHaveBeenCalledTimes( 1 );
			expect( gl.enable ).toHaveBeenCalledWith( gl.SCISSOR_TEST );
			expect( gl.disable ).toHaveBeenCalledWith( gl.SCISSOR_TEST );

			gl.enable.mockClear();
			gl.disable.mockClear();

			state.setStencilTest( true );
			state.setStencilTest( false );

			expect( gl.enable ).toHaveBeenCalledWith( gl.STENCIL_TEST );
			expect( gl.disable ).toHaveBeenCalledWith( gl.STENCIL_TEST );

		} );

		it( 'caches mask, function and operations', () => {

			state.setStencilMask( 0xFF );
			state.setStencilMask( 0xFF );
			expect( gl.stencilMask ).toHaveBeenCalledTimes( 1 );

			state.setStencilFunc( gl.LESS, 1, 0xFF );
			state.setStencilFunc( gl.LESS, 1, 0xFF );
			state.setStencilFunc( gl.LESS, 2, 0xFF );
			expect( gl.stencilFunc ).toHaveBeenCalledTimes( 2 );
			expect( gl.stencilFunc ).toHaveBeenLastCalledWith( gl.LESS, 2, 0xFF );

			state.setStencilOp( gl.KEEP, gl.KEEP, gl.REPLACE );
			state.setStencilOp( gl.KEEP, gl.KEEP, gl.REPLACE );
			state.setStencilOp( gl.ZERO, gl.KEEP, gl.REPLACE );
			expect( gl.stencilOp ).toHaveBeenCalledTimes( 2 );

		} );

	} );

	describe( 'setMaterial()', () => {

		it( 'enables culling for front side materials', () => {

			const material = createMaterial( { side: FrontSide } );

			state.setMaterial( material, false, 0 );

			expect( gl.enable ).toHaveBeenCalledWith( gl.CULL_FACE );
			expect( gl.frontFace ).toHaveBeenCalledWith( gl.CCW );

		} );

		it( 'disables culling for double sided materials', () => {

			const material = createMaterial( { side: DoubleSide } );

			state.setMaterial( material, false, 0 );

			expect( gl.disable ).toHaveBeenCalledWith( gl.CULL_FACE );

		} );

		it( 'flips the winding for back side materials', () => {

			state.setMaterial( createMaterial( { side: BackSide } ), false, 0 );
			expect( gl.frontFace ).toHaveBeenCalledWith( gl.CW );

			state.setMaterial( createMaterial( { side: FrontSide } ), true, 0 );
			expect( gl.frontFace ).toHaveBeenLastCalledWith( gl.CW );

			state.setMaterial( createMaterial( { side: BackSide } ), true, 0 );
			expect( gl.frontFace ).toHaveBeenLastCalledWith( gl.CCW );

		} );

		it( 'disables blending for opaque materials', () => {

			const material = createMaterial( { blending: NormalBlending, transparent: false } );

			state.setMaterial( material, false, 0 );

			expect( gl.enable ).not.toHaveBeenCalledWith( gl.BLEND );

		} );

		it( 'enables blending for transparent materials', () => {

			const material = createMaterial( { blending: NormalBlending, transparent: true } );

			state.setMaterial( material, false, 0 );

			expect( gl.enable ).toHaveBeenCalledWith( gl.BLEND );
			expect( gl.blendFuncSeparate ).toHaveBeenCalledWith( gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA );

		} );

		it( 'applies depth, color and polygon offset state', () => {

			const material = createMaterial( {
				depthTest: false,
				depthWrite: false,
				colorWrite: false,
				polygonOffset: true,
				polygonOffsetFactor: 2,
				polygonOffsetUnits: 3
			} );

			state.setMaterial( material, false, 0 );

			expect( gl.disable ).toHaveBeenCalledWith( gl.DEPTH_TEST );
			expect( gl.depthMask ).toHaveBeenCalledWith( false );
			expect( gl.colorMask ).toHaveBeenCalledWith( false, false, false, false );
			expect( gl.enable ).toHaveBeenCalledWith( gl.POLYGON_OFFSET_FILL );
			expect( gl.polygonOffset ).toHaveBeenCalledWith( 2, 3 );

		} );

		it( 'applies stencil state for stencil writing materials', () => {

			const material = createMaterial( { stencilWrite: true, stencilWriteMask: 0xFF, stencilRef: 2 } );

			state.setMaterial( material, false, 0 );

			expect( gl.enable ).toHaveBeenCalledWith( gl.STENCIL_TEST );
			expect( gl.stencilMask ).toHaveBeenCalledWith( 0xFF );
			expect( gl.stencilFunc ).toHaveBeenCalledWith( material.stencilFunc, 2, material.stencilFuncMask );
			expect( gl.stencilOp ).toHaveBeenCalledWith( material.stencilFail, material.stencilZFail, material.stencilZPass );

		} );

		it( 'enables alpha to coverage only with multisampling', () => {

			const material = createMaterial( { alphaToCoverage: true } );

			state.setMaterial( material, false, 0 );
			expect( gl.disable ).toHaveBeenCalledWith( gl.SAMPLE_ALPHA_TO_COVERAGE );

			backend.renderer.currentSamples = 4;
			state.setMaterial( material, false, 0 );
			expect( gl.enable ).toHaveBeenCalledWith( gl.SAMPLE_ALPHA_TO_COVERAGE );

		} );

		it( 'enables the hardware clipping planes and caches the count', () => {

			state.setMaterial( createMaterial(), false, 2 );

			const CLIP_DISTANCE0 = 0x3000;

			expect( gl.enable ).toHaveBeenCalledWith( CLIP_DISTANCE0 );
			expect( gl.enable ).toHaveBeenCalledWith( CLIP_DISTANCE0 + 1 );
			expect( gl.disable ).toHaveBeenCalledWith( CLIP_DISTANCE0 + 2 );
			expect( gl.disable ).toHaveBeenCalledWith( CLIP_DISTANCE0 + 7 );
			expect( state.currentClippingPlanes ).toBe( 2 );

			gl.enable.mockClear();
			gl.disable.mockClear();

			state.setMaterial( createMaterial(), false, 2 );

			expect( gl.enable ).not.toHaveBeenCalledWith( CLIP_DISTANCE0 );

		} );

	} );

	describe( 'setPolygonOffset()', () => {

		it( 'enables and caches the offset', () => {

			state.setPolygonOffset( true, 1, 2 );
			state.setPolygonOffset( true, 1, 2 );
			state.setPolygonOffset( true, 3, 4 );

			expect( gl.enable ).toHaveBeenCalledWith( gl.POLYGON_OFFSET_FILL );
			expect( gl.polygonOffset ).toHaveBeenCalledTimes( 2 );
			expect( gl.polygonOffset ).toHaveBeenNthCalledWith( 1, 1, 2 );
			expect( gl.polygonOffset ).toHaveBeenNthCalledWith( 2, 3, 4 );

		} );

		it( 'disables the fill mode', () => {

			state.setPolygonOffset( false, 0, 0 );

			expect( gl.disable ).toHaveBeenCalledWith( gl.POLYGON_OFFSET_FILL );
			expect( gl.polygonOffset ).not.toHaveBeenCalled();

		} );

		it( 'inverts the offset for reversed depth buffers', () => {

			state.setReversedDepth( true );
			state.setPolygonOffset( true, 2, 3 );

			expect( gl.polygonOffset ).toHaveBeenCalledWith( - 2, - 3 );

		} );

	} );

	describe( 'programs and vertex state', () => {

		it( 'reports whether a program has been changed', () => {

			const programA = { id: 'a' };
			const programB = { id: 'b' };

			expect( state.useProgram( programA ) ).toBe( true );
			expect( state.useProgram( programA ) ).toBe( false );
			expect( state.useProgram( programB ) ).toBe( true );

			expect( gl.useProgram ).toHaveBeenCalledTimes( 2 );
			expect( state.currentProgram ).toBe( programB );

		} );

		it( 'binds a VAO and an optional index buffer', () => {

			const vao = { id: 'vao' };
			const indexBuffer = { id: 'index' };

			expect( state.setVertexState( vao, indexBuffer ) ).toBe( true );
			expect( gl.bindVertexArray ).toHaveBeenCalledWith( vao );
			expect( gl.bindBuffer ).toHaveBeenCalledWith( gl.ELEMENT_ARRAY_BUFFER, indexBuffer );
			expect( state.currentIndex ).toBe( indexBuffer );

			expect( state.setVertexState( vao, indexBuffer ) ).toBe( false );
			expect( gl.bindVertexArray ).toHaveBeenCalledTimes( 1 );

			expect( state.setVertexState( vao ) ).toBe( true );
			expect( gl.bindBuffer ).toHaveBeenCalledTimes( 1 );

		} );

		it( 'resets the vertex state', () => {

			state.setVertexState( { id: 'vao' }, { id: 'index' } );
			gl.bindVertexArray.mockClear();
