{"command": "cd /testbed; cat > test/renderers/webgl-fallback/utils/webglTextureUtils.test.js <<'EOF'
import { jest, beforeEach, afterEach } from '@jest/globals';

import WebGLTextureUtils from '../../../../src/renderers/webgl-fallback/utils/WebGLTextureUtils.js';
import { setConsoleFunction } from '../../../../src/utils.js';
import { Texture } from '../../../../src/textures/Texture.js';
import { DataTexture } from '../../../../src/textures/DataTexture.js';
import { CubeTexture } from '../../../../src/textures/CubeTexture.js';
import { Data3DTexture } from '../../../../src/textures/Data3DTexture.js';
import { DataArrayTexture } from '../../../../src/textures/DataArrayTexture.js';
import { CompressedTexture } from '../../../../src/textures/CompressedTexture.js';
import {
	RGBAFormat, RGBAIntegerFormat, RGBFormat, RedFormat, RGFormat, DepthFormat, DepthStencilFormat,
	UnsignedByteType, FloatType, HalfFloatType, UnsignedShortType, IntType, UnsignedIntType,
	UnsignedInt248Type, SRGBColorSpace, NoColorSpace,
	RepeatWrapping, ClampToEdgeWrapping, NearestFilter, NearestMipmapLinearFilter, LinearFilter,
	LinearMipmapLinearFilter, LessEqualCompare
} from '../../../../src/constants.js';
import { createMockBackend, createMockGL } from './mockWebGL.js';

const anisotropyExt = {
	MAX_TEXTURE_MAX_ANISOTROPY_EXT: 0x84FF,
	TEXTURE_MAX_ANISOTROPY_EXT: 0x84FE
};

const norm16Ext = { R16_EXT: 9001, RG16_EXT: 9002, RGB16_EXT: 9003, R16_SNORM_EXT: 9004 };

describe( 'WebGLTextureUtils', () => {

	let backend, gl, state, utils, messages;

	beforeEach( () => {

		messages = [];
		setConsoleFunction( ( type, message, ...params ) => messages.push( { type, message, params } ) );

		backend = createMockBackend( {
			glOptions: {
				extensions: {
					EXT_texture_filter_anisotropic: anisotropyExt,
					EXT_texture_norm16: norm16Ext
				}
			}
		} );
		gl = backend.gl;
		state = backend.state;
		backend.textureUtils = new WebGLTextureUtils( backend );
		utils = backend.textureUtils;

		// `setTextureParameters` uses the capabilities of the backend
		gl.setParameter( anisotropyExt.MAX_TEXTURE_MAX_ANISOTROPY_EXT, 8 );

	} );

	afterEach( () => {

		setConsoleFunction( null );

	} );

	function createTexture( data = new Uint8Array( 4 ), width = 1, height = 1 ) {

		return new DataTexture( data, width, height );

	}

	describe( 'constructor', () => {

		it( 'references the backend context and extensions', () => {

			expect( utils.backend ).toBe( backend );
			expect( utils.gl ).toBe( gl );
			expect( utils.extensions ).toBe( backend.extensions );
			expect( utils.defaultTextures ).toEqual( {} );
			expect( utils._srcFramebuffer ).toBeNull();
			expect( utils._dstFramebuffer ).toBeNull();

		} );

	} );

	describe( 'getGLTextureType()', () => {

		it( 'derives the binding point from the texture type', () => {

			expect( utils.getGLTextureType( new Texture() ) ).toBe( gl.TEXTURE_2D );
			expect( utils.getGLTextureType( new CubeTexture() ) ).toBe( gl.TEXTURE_CUBE_MAP );
			expect( utils.getGLTextureType( new DataArrayTexture( new Uint8Array( 16 ), 2, 2, 1 ) ) ).toBe( gl.TEXTURE_2D_ARRAY );
			expect( utils.getGLTextureType( new Data3DTexture( new Uint8Array( 16 ), 2, 2, 2 ) ) ).toBe( gl.TEXTURE_3D );
			expect( utils.getGLTextureType( { isArrayTexture: true } ) ).toBe( gl.TEXTURE_2D_ARRAY );
			expect( utils.getGLTextureType( { isCompressedArrayTexture: true } ) ).toBe( gl.TEXTURE_2D_ARRAY );

		} );

	} );

	describe( 'getInternalFormat()', () => {

		it( 'returns a named internal format when the context knows it', () => {

			expect( utils.getInternalFormat( 'RGBA8', gl.RGBA, gl.UNSIGNED_BYTE, false, NoColorSpace ) ).toBe( gl.RGBA8 );

		} );

		it( 'warns about unknown internal format names and falls back', () => {

			expect( utils.getInternalFormat( 'NOT_A_FORMAT', gl.RGBA, gl.UNSIGNED_BYTE, false, NoColorSpace ) ).toBe( gl.RGBA8 );
			expect( messages[ 0 ].type ).toBe( 'warn' );
			expect( messages[ 0 ].message ).toContain( 'Attempt to use non-existing WebGL internal format' );

		} );

		it( 'selects an sRGB internal format for sRGB color spaces', () => {

			expect( utils.getInternalFormat( null, gl.RGBA, gl.UNSIGNED_BYTE, false, SRGBColorSpace ) ).toBe( gl.SRGB8_ALPHA8 );
			expect( utils.getInternalFormat( null, gl.RGBA, gl.UNSIGNED_BYTE, false, NoColorSpace ) ).toBe( gl.RGBA8 );

		} );

		it( 'maps sized formats per channel and type', () => {

			expect( utils.getInternalFormat( null, gl.RED, gl.FLOAT, false, NoColorSpace ) ).toBe( gl.R32F );
			expect( utils.getInternalFormat( null, gl.RED, gl.HALF_FLOAT, false, NoColorSpace ) ).toBe( gl.R16F );
			expect( utils.getInternalFormat( null, gl.RED, gl.UNSIGNED_BYTE, false, NoColorSpace ) ).toBe( gl.R8 );
			expect( utils.getInternalFormat( null, gl.RG, gl.HALF_FLOAT, false, NoColorSpace ) ).toBe( gl.RG16F );
			expect( utils.getInternalFormat( null, gl.RGB, gl.UNSIGNED_BYTE, false, NoColorSpace ) ).toBe( gl.RGB8 );
			expect( utils.getInternalFormat( null, gl.RGB, gl.UNSIGNED_BYTE, false, SRGBColorSpace ) ).toBe( gl.SRGB8 );
			expect( utils.getInternalFormat( null, gl.RGBA, gl.HALF_FLOAT, false, NoColorSpace ) ).toBe( gl.RGBA16F );
			expect( utils.getInternalFormat( null, gl.RGBA, gl.FLOAT, false, NoColorSpace ) ).toBe( gl.RGBA32F );

		} );

		it( 'maps integer formats', () => {

			expect( utils.getInternalFormat( null, gl.RED_INTEGER, gl.UNSIGNED_INT, false, NoColorSpace ) ).toBe( gl.R32UI );
			expect( utils.getInternalFormat( null, gl.RGBA_INTEGER, gl.INT, false, NoColorSpace ) ).toBe( gl.RGBA32I );
			expect( utils.getInternalFormat( null, gl.RGBA_INTEGER, gl.UNSIGNED_BYTE, false, NoColorSpace ) ).toBe( gl.RGBA8UI );

		} );

		it( 'maps depth and stencil formats', () => {

			expect( utils.getInternalFormat( null, gl.DEPTH_COMPONENT, gl.UNSIGNED_INT, false, NoColorSpace ) ).toBe( gl.DEPTH_COMPONENT24 );
			expect( utils.getInternalFormat( null, gl.DEPTH_COMPONENT, gl.UNSIGNED_SHORT, false, NoColorSpace ) ).toBe( gl.DEPTH_COMPONENT16 );
			expect( utils.getInternalFormat( null, gl.DEPTH_STENCIL, gl.UNSIGNED_INT_24_8, false, NoColorSpace ) ).toBe( gl.DEPTH24_STENCIL8 );
			expect( utils.getInternalFormat( null, gl.DEPTH_STENCIL, gl.FLOAT, false, NoColorSpace ) ).toBe( gl.DEPTH32F_STENCIL8 );

		} );

		it( 'requests color buffer float support for float formats', () => {

			utils.getInternalFormat( null, gl.RGBA, gl.FLOAT, false, NoColorSpace );

			expect( backend.extensions.get( 'EXT_color_buffer_float' ) ).toBeNull();
			expect( gl.getExtension ).toHaveBeenCalledWith( 'EXT_color_buffer_float' );

		} );

		it( 'uses the norm16 extension for normalized 16 bit formats', () => {

			expect( utils.getInternalFormat( null, gl.RED, gl.UNSIGNED_SHORT, true, NoColorSpace ) ).toBe( norm16Ext.R16_EXT );
			expect( utils.getInternalFormat( null, gl.RG, gl.UNSIGNED_SHORT, true, NoColorSpace ) ).toBe( norm16Ext.RG16_EXT );

		} );

		it( 'warns when normalized formats are used without the norm16 extension', () => {

			const plainGl = createMockGL();
			const plainBackend = createMockBackend( { gl: plainGl } );
			const plainUtils = new WebGLTextureUtils( plainBackend );

			expect( plainUtils.getInternalFormat( null, plainGl.RED, plainGl.UNSIGNED_SHORT, true, NoColorSpace ) ).toBe( plainGl.RED );
			expect( messages.some( ( m ) => m.message.includes( 'Unable to use normalized textures' ) ) ).toBe( true );

		} );

		it( 'falls back to the WebGL format for unmapped combinations', () => {

			expect( utils.getInternalFormat( null, gl.ALPHA, gl.UNSIGNED_BYTE, false, NoColorSpace ) ).toBe( gl.ALPHA );

		} );

	} );

	describe( 'setTextureParameters()', () => {

		it( 'uploads the pixel storage and sampling parameters of the texture', () => {

			const texture = new Texture();
			texture.wrapS = RepeatWrapping;
			texture.wrapT = ClampToEdgeWrapping;
			texture.magFilter = NearestFilter;
			texture.minFilter = NearestFilter;

			utils.setTextureParameters( gl.TEXTURE_2D, texture );

			expect( state.parameters[ gl.UNPACK_FLIP_Y_WEBGL ] ).toBe( texture.flipY );
			expect( state.parameters[ gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL ] ).toBe( texture.premultiplyAlpha );
			expect( state.parameters[ gl.UNPACK_ALIGNMENT ] ).toBe( texture.unpackAlignment );
			expect( state.parameters[ gl.UNPACK_COLORSPACE_CONVERSION_WEBGL ] ).toBe( gl.NONE );

			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT );
			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE );
			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST );
			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST );

		} );

		it( 'sets the R wrapping for 3D textures', () => {

			const texture = new Texture();

			utils.setTextureParameters( gl.TEXTURE_3D, texture );

			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_3D, gl.TEXTURE_WRAP_R, gl.CLAMP_TO_EDGE );

		} );

		it( 'uses browser default conversion for color managed textures', () => {

			const texture = new Texture();
			texture.colorSpace = SRGBColorSpace;

			utils.setTextureParameters( gl.TEXTURE_2D, texture );

			expect( state.parameters[ gl.UNPACK_COLORSPACE_CONVERSION_WEBGL ] ).toBe( gl.BROWSER_DEFAULT_WEBGL );

		} );

		it( 'upgrades linear filtering to mipmap filtering when mipmaps exist', () => {

			const texture = new Texture();
			texture.minFilter = LinearFilter;
			texture.mipmaps = [ { width: 1, height: 1, data: new Uint8Array( 4 ) } ];

			utils.setTextureParameters( gl.TEXTURE_2D, texture );

			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR );

		} );

		it( 'configures the depth compare mode', () => {

			const texture = new Texture();
			texture.compareFunction = LessEqualCompare;

			utils.setTextureParameters( gl.TEXTURE_2D, texture );

			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_COMPARE_MODE, gl.COMPARE_REF_TO_TEXTURE );
			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_COMPARE_FUNC, gl.LEQUAL );

		} );

		it( 'applies the anisotropy limit of the device', () => {

			const texture = new Texture();
			texture.minFilter = LinearMipmapLinearFilter;
			texture.anisotropy = 16;

			utils.setTextureParameters( gl.TEXTURE_2D, texture );

			expect( gl.texParameterf ).toHaveBeenCalledWith( gl.TEXTURE_2D, anisotropyExt.TEXTURE_MAX_ANISOTROPY_EXT, 8 );

		} );

		it( 'skips anisotropy for nearest filtering', () => {

			const texture = new Texture();
			texture.magFilter = NearestFilter;
			texture.minFilter = LinearMipmapLinearFilter;
			texture.anisotropy = 16;

			utils.setTextureParameters( gl.TEXTURE_2D, texture );

			expect( gl.texParameterf ).not.toHaveBeenCalled();

		} );

		it( 'skips anisotropy for textures without mipmap filtering', () => {

			const texture = new Texture();
			texture.minFilter = LinearFilter;
			texture.anisotropy = 16;

			utils.setTextureParameters( gl.TEXTURE_2D, texture );

			expect( gl.texParameterf ).not.toHaveBeenCalled();

		} );

		it( 'skips anisotropy for float textures without linear float support', () => {

			const texture = new Texture();
			texture.type = FloatType;
			texture.minFilter = NearestMipmapLinearFilter;
			texture.anisotropy = 16;

			utils.setTextureParameters( gl.TEXTURE_2D, texture );

			expect( gl.texParameterf ).not.toHaveBeenCalled();

		} );

	} );

	describe( 'createDefaultTexture()', () => {

		it( 'creates one placeholder texture per binding point', () => {

			const textureA = new Texture();
			const textureB = new Texture();

			utils.createDefaultTexture( textureA );
			utils.createDefaultTexture( textureB );

			expect( gl.createTexture ).toHaveBeenCalledTimes( 1 );
			expect( utils.defaultTextures[ gl.TEXTURE_2D ] ).toBeDefined();
			expect( backend.get( textureA ).textureGPU ).toBe( utils.defaultTextures[ gl.TEXTURE_2D ] );
			expect( backend.get( textureB ).textureGPU ).toBe( utils.defaultTextures[ gl.TEXTURE_2D ] );
			expect( backend.get( textureA ).glTextureType ).toBe( gl.TEXTURE_2D );

			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST );
			expect( gl.texParameteri ).toHaveBeenCalledWith( gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST );

		} );

		it( 'creates a separate placeholder for cube textures', () => {

			utils.createDefaultTexture( new Texture() );
			utils.createDefaultTexture( new CubeTexture() );

			expect( gl.createTexture ).toHaveBeenCalledTimes( 2 );
			expect( utils.defaultTextures[ gl.TEXTURE_CUBE_MAP ] ).not.toBe( utils.defaultTextures[ gl.TEXTURE_2D ] );

		} );

	} );

	describe( 'createTexture()', () => {

		it( 'allocates a 2D texture storage', () => {

			const texture = createTexture( new Uint8Array( 16 ), 2, 2 );
			texture.colorSpace = SRGBColorSpace;

			utils.createTexture( texture, { levels: 1, width: 2, height: 2, depth: 1 } );

			const data = backend.get( texture );

			expect( gl.createTexture ).toHaveBeenCalledTimes( 1 );
			expect( data.glTextureType ).toBe( gl.TEXTURE_2D );
			expect( data.glFormat ).toBe( gl.RGBA );
			expect( data.glType ).toBe( gl.UNSIGNED_BYTE );
			expect( data.glInternalFormat ).toBe( gl.SRGB8_ALPHA8 );
			expect( gl.texStorage2D ).toHaveBeenCalledWith( gl.TEXTURE_2D, 1, gl.SRGB8_ALPHA8, 2, 2 );

		} );

		it( 'allocates 3D storage for array textures', () => {

			const texture = new DataArrayTexture( new Uint8Array( 32 ), 2, 2, 2 );

			utils.createTexture( texture, { levels: 1, width: 2, height: 2, depth: 2 } );

			expect( gl.texStorage3D ).toHaveBeenCalledWith( gl.TEXTURE_2D_ARRAY, 1, gl.RGBA8, 2, 2, 2 );
			expect( gl.texStorage2D ).not.toHaveBeenCalled();

		} );

		it( 'allocates 3D storage for 3D textures', () => {

			const texture = new Data3DTexture( new Uint8Array( 32 ), 2, 2, 2 );

			utils.createTexture( texture, { levels: 1, width: 2, height: 2, depth: 2 } );

			expect( gl.texStorage3D ).toHaveBeenCalledWith( gl.TEXTURE_3D, 1, gl.RGBA8, 2, 2, 2 );

		} );

		it( 'reuses the source texture of external textures', () => {

			const sourceTexture = { id: 'external' };
			const texture = Object.assign( new Texture(), { isExternalTexture: true, sourceTexture } );

			utils.createTexture( texture, {} );

			expect( gl.createTexture ).not.toHaveBeenCalled();
			expect( backend.get( texture ).textureGPU ).toBe( sourceTexture );

		} );

		it( 'defers the storage allocation for video textures', () => {

			const texture = Object.assign( new Texture(), { isVideoTexture: true } );

			utils.createTexture( texture, { levels: 1, width: 2, height: 2, depth: 1 } );

			expect( gl.texStorage2D ).not.toHaveBeenCalled();
			expect( backend.get( texture ).textureGPU ).toBeDefined();

		} );

	} );

	describe( 'copyBufferToTexture()', () => {

		it( 'uploads the bound pixel unpack buffer', () => {

			const texture = createTexture( new Uint8Array( 16 ), 2, 2 );
			utils.createTexture( texture, { levels: 1, width: 2, height: 2, depth: 1 } );

			const buffer = { id: 'pbo' };
			texture.source.data = { width: 2, height: 2 };

			utils.copyBufferToTexture( buffer, texture );

			const data = backend.get( texture );

			expect( gl.bindBuffer ).toHaveBeenCalledWith( gl.PIXEL_UNPACK_BUFFER, buffer );
			expect( gl.texSubImage2D ).toHaveBeenCalledWith( gl.TEXTURE_2D, 0, 0, 0, 2, 2, data.glFormat, data.glType, 0 );
			expect( gl.bindBuffer ).toHaveBeenLastCalledWith( gl.PIXEL_UNPACK_BUFFER, null );

		} );

	} );

	describe( 'updateTexture()', () => {

		it( 'ignores render target textures', () => {

			const texture = Object.assign( createTexture( new Uint8Array( 16 ), 2, 2 ), { isRenderTargetTexture: true } );
			utils.createTexture( texture, { levels: 1, width: 2, height: 2, depth: 1 } );

			utils.updateTexture( texture, { width: 2, height: 2, image: texture.image } );

			expect( gl.texSubImage2D ).not.toHaveBeenCalled();

		} );

		it( 'ignores textures without GPU data', () => {

			const texture = createTexture();

			expect( () => utils.updateTexture( texture, { width: 1, height: 1, image: texture.image } ) ).not.toThrow();
			expect( gl.texSubImage2D ).not.toHaveBeenCalled();

		} );

		it( 'uploads data textures', () => {

			const texture = createTexture( new Uint8Array( 16 ), 2, 2 );
			utils.createTexture( texture, { levels: 1, width: 2, height: 2, depth: 1 } );

			utils.updateTexture( texture, { width: 2, height: 2, image: texture.image } );

			expect( gl.texSubImage2D ).toHaveBeenCalledWith( gl.TEXTURE_2D, 0, 0, 0, 2, 2, gl.RGBA, gl.UNSIGNED_BYTE, texture.image.data );

		} );

		it( 'uploads every cube face', () => {

			const image = { width: 1, height: 1, data: new Uint8Array( 4 ) };
			const texture = new CubeTexture( [ image, image, image, image, image, image ] );
			utils.createTexture( texture, { levels: 1, width: 1, height: 1, depth: 1 } );

			utils.updateTexture( texture, { width: 1, height: 1, images: texture.image } );

			expect( gl.texSubImage2D ).toHaveBeenCalledTimes( 6 );
			expect( gl.texSubImage2D ).toHaveBeenNthCalledWith( 1, gl.TEXTURE_CUBE_MAP_POSITIVE_X, 0, 0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, image.data );

		} );

		it( 'uploads array textures layer by layer', () => {

			const texture = new DataArrayTexture( new Uint8Array( 16 ), 2, 2, 1 );
			utils.createTexture( texture, { levels: 1, width: 2, height: 2, depth: 1 } );

			texture.layerUpdates.add( 0 );

			utils.updateTexture( texture, { width: 2, height: 2, image: texture.image, depth: 1 } );

