import { describe, test, expect } from '@jest/globals';
import { WebXRDepthSensing } from '../../../src/renderers/webxr/WebXRDepthSensing.js';
import { ExternalTexture } from '../../../src/textures/ExternalTexture.js';
import { Mesh } from '../../../src/objects/Mesh.js';
import { PlaneGeometry } from '../../../src/geometries/PlaneGeometry.js';
import { ShaderMaterial } from '../../../src/materials/ShaderMaterial.js';

function cameraXRWithViewport( z, w ) {
	return { cameras: [ { viewport: { x: 0, y: 0, z, w } } ] };
}

describe( 'WebXRDepthSensing', () => {

	test( 'starts with no texture or mesh and zeroed depth range', () => {
		const depthSensing = new WebXRDepthSensing();

		expect( depthSensing.texture ).toBeNull();
		expect( depthSensing.mesh ).toBeNull();
		expect( depthSensing.depthNear ).toBe( 0 );
		expect( depthSensing.depthFar ).toBe( 0 );
		expect( depthSensing.getDepthTexture() ).toBeNull();
		expect( depthSensing.getMesh( cameraXRWithViewport( 100, 100 ) ) ).toBeNull();
	} );

	test( 'init wraps the XR depth texture and adopts a differing render-state depth range', () => {
		const depthSensing = new WebXRDepthSensing();
		const sourceTexture = { id: 'depth-source' };
		const depthData = { texture: sourceTexture, depthNear: 0.25, depthFar: 12 };
		const renderState = { depthNear: 1, depthFar: 100 };

		depthSensing.init( depthData, renderState );

		expect( depthSensing.texture ).toBeInstanceOf( ExternalTexture );
		expect( depthSensing.texture.sourceTexture ).toBe( sourceTexture );
		expect( depthSensing.texture.isExternalTexture ).toBe( true );
		expect( depthSensing.getDepthTexture() ).toBe( depthSensing.texture );
		expect( depthSensing.depthNear ).toBe( 0.25 );
		expect( depthSensing.depthFar ).toBe( 12 );
	} );

	test( 'init keeps the zero depth range when it matches the render state', () => {
		const depthSensing = new WebXRDepthSensing();

		depthSensing.init(
			{ texture: {}, depthNear: 0.5, depthFar: 20 },
			{ depthNear: 0.5, depthFar: 20 }
		);

		expect( depthSensing.depthNear ).toBe( 0 );
		expect( depthSensing.depthFar ).toBe( 0 );
	} );

	test( 'init is idempotent and does not replace an existing texture or depth range', () => {
		const depthSensing = new WebXRDepthSensing();
		const firstTexture = { id: 'first' };
		const secondTexture = { id: 'second' };

		depthSensing.init( { texture: firstTexture, depthNear: 0.1, depthFar: 10 }, { depthNear: 1, depthFar: 100 } );
		const firstExternalTexture = depthSensing.texture;
		depthSensing.init( { texture: secondTexture, depthNear: 0.2, depthFar: 20 }, { depthNear: 1, depthFar: 100 } );

		expect( depthSensing.texture ).toBe( firstExternalTexture );
		expect( depthSensing.texture.sourceTexture ).toBe( firstTexture );
		expect( depthSensing.depthNear ).toBe( 0.1 );
		expect( depthSensing.depthFar ).toBe( 10 );
	} );

	test( 'getMesh lazily builds a plane whose shader samples the depth texture and viewport', () => {
		const depthSensing = new WebXRDepthSensing();
		depthSensing.init( { texture: { id: 'depth' }, depthNear: 0.2, depthFar: 15 }, { depthNear: 1, depthFar: 100 } );

		const mesh = depthSensing.getMesh( cameraXRWithViewport( 640, 320 ) );

		expect( mesh ).toBeInstanceOf( Mesh );
		expect( mesh.geometry ).toBeInstanceOf( PlaneGeometry );
		expect( mesh.geometry.parameters.width ).toBe( 20 );
		expect( mesh.geometry.parameters.height ).toBe( 20 );
		expect( mesh.material ).toBeInstanceOf( ShaderMaterial );
		expect( mesh.material.uniforms.depthColor.value ).toBe( depthSensing.texture );
		expect( mesh.material.uniforms.depthWidth.value ).toBe( 640 );
		expect( mesh.material.uniforms.depthHeight.value ).toBe( 320 );
		expect( mesh.material.vertexShader ).toContain( 'gl_Position' );
		expect( mesh.material.fragmentShader ).toContain( 'uniform sampler2DArray depthColor' );
		expect( depthSensing.mesh ).toBe( mesh );
	} );

	test( 'getMesh caches the first mesh and its viewport-derived uniforms', () => {
		const depthSensing = new WebXRDepthSensing();
		depthSensing.init( { texture: {}, depthNear: 0.2, depthFar: 15 }, { depthNear: 1, depthFar: 100 } );
		const first = depthSensing.getMesh( cameraXRWithViewport( 640, 320 ) );

		const second = depthSensing.getMesh( cameraXRWithViewport( 1280, 720 ) );

		expect( second ).toBe( first );
		expect( second.material.uniforms.depthWidth.value ).toBe( 640 );
		expect( second.material.uniforms.depthHeight.value ).toBe( 320 );
	} );

	test( 'reset clears the texture and mesh but depth range remains available until reinitialization', () => {
		const depthSensing = new WebXRDepthSensing();
		depthSensing.init( { texture: {}, depthNear: 0.2, depthFar: 15 }, { depthNear: 1, depthFar: 100 } );
		depthSensing.getMesh( cameraXRWithViewport( 100, 100 ) );

		depthSensing.reset();

		expect( depthSensing.texture ).toBeNull();
		expect( depthSensing.mesh ).toBeNull();
		expect( depthSensing.getDepthTexture() ).toBeNull();
		expect( depthSensing.getMesh( cameraXRWithViewport( 100, 100 ) ) ).toBeNull();
	} );

} );
EOF
