			animationFrames.push( callback );
			return animationFrames.length;
		} ),
		cancelAnimationFrame: jest.fn(),
		runNextAnimationFrame( time, frame ) {
			const callback = animationFrames.shift();
			if ( ! callback ) throw new Error( 'No queued animation frame' );
			callback( time, frame );
		},
		get queuedAnimationFrames() {
			return animationFrames.length;
		},
		referenceSpace
	} );
}

function makeView( index, x = 0, y = 0, z = 0 ) {
	return {
		index,
		camera: null,
		transform: { matrix: translatedMatrix( x, y, z ) },
		projectionMatrix: identityMatrix.slice()
	};
}

function makeFrame( session, {
	views = [ makeView( 0 ), makeView( 1 ) ],
	detectedPlanes = null,
	targetRayPose = null,
	gripPose = null
} = {} ) {
	return {
		session,
		detectedPlanes,
