	constructor( session, gl, layerInit ) {
		this.session = session;
		this.gl = gl;
		this.layerInit = layerInit;
		this.framebuffer = { name: 'xr-framebuffer' };
		this.framebufferWidth = 1200;
		this.framebufferHeight = 600;
		this.ignoreDepthValues = false;
		this.fixedFoveation = 0;
	}

	getViewport( view ) {
		return { x: view.index * 320, y: 0, width: 320, height: 240 };
	}

}

class FakeXRWebGLBinding {

	constructor( session, gl ) {
		this.session = session;
		this.gl = gl;
