		const targetRay = manager.getController( 0 );
		const grip = manager.getControllerGrip( 0 );
		const hand = manager.getHand( 0 );
		const connected = jest.fn();
		const disconnected = jest.fn();
		const selected = jest.fn();
		targetRay.addEventListener( 'connected', connected );
		targetRay.addEventListener( 'disconnected', disconnected );
		targetRay.addEventListener( 'select', selected );
		await startBaseSession( manager, session );

		const wrist = { jointName: 'wrist' };
		const inputSource = makeInputSource( 'primary', {
			hand: new Map( [ [ 'wrist', wrist ] ] )
		} );
		session.emit( 'inputsourceschange', { added: [ inputSource ], removed: [] } );

		expect( connected ).toHaveBeenCalledTimes( 1 );
		expect( connected.mock.calls[ 0 ][ 0 ].data ).toBe( inputSource );
		expect( hand.joints.wrist ).toBeInstanceOf( Group );

		const frame = makeFrame( session, {
			views: [],
			targetRayPose: { transform: { matrix: translatedMatrix( 1, 2, 3 ) } },
			gripPose: { transform: { matrix: translatedMatrix( 4, 5, 6 ) } }
		} );
		session.emit( 'select', { inputSource, frame } );

		expect( selected ).toHaveBeenCalledTimes( 1 );
		expect( selected.mock.calls[ 0 ][ 0 ].data ).toBe( inputSource );
		expect( targetRay.visible ).toBe( true );
		expect( targetRay.position.toArray() ).toEqual( [ 1, 2, 3 ] );
		expect( grip.visible ).toBe( true );
		expect( frame.getPose ).toHaveBeenCalledWith( inputSource.targetRaySpace, session.referenceSpace );

		session.emit( 'inputsourceschange', { added: [], removed: [ inputSource ] } );

		expect( disconnected ).toHaveBeenCalledTimes( 1 );
		expect( disconnected.mock.calls[ 0 ][ 0 ].data ).toBe( inputSource );
		expect( targetRay.visible ).toBe( false );
		expect( grip.visible ).toBe( false );
		expect( hand.visible ).toBe( false );
	} );

	test( 'reuses vacant controller slots and ignores extra input sources when all slots are occupied', async () => {
		const manager = new WebXRManager( createRenderer(), createGL() );
		const session = createSession();
		const targetRay = manager.getController( 0 );
		const connected = jest.fn();
		const disconnected = jest.fn();
		targetRay.addEventListener( 'connected', connected );
		targetRay.addEventListener( 'disconnected', disconnected );
		await startBaseSession( manager, session );

		const first = makeInputSource( 'first' );
		const second = makeInputSource( 'second' );
		session.emit( 'inputsourceschange', { added: [ first, second ], removed: [] } );

		expect( connected ).toHaveBeenCalledTimes( 1 );
		expect( connected.mock.calls[ 0 ][ 0 ].data ).toBe( first );

		session.emit( 'inputsourceschange', { added: [], removed: [ first ] } );
		expect( disconnected ).toHaveBeenCalledTimes( 1 );
		expect( disconnected.mock.calls[ 0 ][ 0 ].data ).toBe( first );

		session.emit( 'inputsourceschange', { added: [ second ], removed: [] } );
		expect( connected ).toHaveBeenCalledTimes( 2 );
		expect( connected.mock.calls[ 1 ][ 0 ].data ).toBe( second );
	} );

	test( 'drives XR cameras, app animation callbacks, frame access, and plane events', async () => {
		const renderer = createRenderer();
		const manager = new WebXRManager( renderer, createGL() );
		const session = createSession();
		const baseLayer = await startBaseSession( manager, session );
		const appLoop = jest.fn();
		const planesDetected = jest.fn();
		manager.setAnimationLoop( appLoop );
		manager.addEventListener( 'planesdetected', planesDetected );
		const views = [ makeView( 0, 1, 2, 3 ), makeView( 1, 4, 5, 6 ) ];
		const frame = makeFrame( session, { views, detectedPlanes: { planes: [] } } );
		let frameSeenByApp;

		manager.setAnimationLoop( ( time, xrFrame ) => {
			frameSeenByApp = manager.getFrame();
			appLoop( time, xrFrame );
		} );
		session.runNextAnimationFrame( 12.5, frame );

		const camera = manager.getCamera();
		expect( camera.cameras ).toHaveLength( 2 );
		expect( camera.cameras[ 0 ].position.toArray() ).toEqual( [ 1, 2, 3 ] );
		expect( camera.cameras[ 1 ].position.toArray() ).toEqual( [ 4, 5, 6 ] );
		expect( camera.cameras[ 0 ].viewport.toArray() ).toEqual( [ 0, 0, 320, 240 ] );
		expect( camera.cameras[ 1 ].viewport.toArray() ).toEqual( [ 320, 0, 320, 240 ] );
		expect( renderer.setRenderTargetFramebuffer ).toHaveBeenCalledWith( expect.objectContaining( { isXRRenderTarget: true } ), baseLayer.framebuffer );
		expect( renderer.setRenderTarget ).toHaveBeenCalledWith( expect.objectContaining( { isXRRenderTarget: true } ) );
		expect( appLoop ).toHaveBeenCalledWith( 12.5, frame );
		expect( frameSeenByApp ).toBe( frame );
		expect( manager.getFrame() ).toBeNull();
		expect( planesDetected ).toHaveBeenCalledTimes( 1 );
		expect( planesDetected.mock.calls[ 0 ][ 0 ].data ).toBe( frame );
		expect( session.queuedAnimationFrames ).toBe( 1 );
	} );

	test( 'projection rendering wires view sub-images into the XR render target', async () => {
