		await startProjectionSession( manager, session );
		const frame = makeFrame( session, { views: [ makeView( 0 ), makeView( 1 ) ] } );

		session.runNextAnimationFrame( 1, frame );

		expect( renderer.setRenderTargetTextures ).toHaveBeenCalledWith(
			expect.objectContaining( { isXRRenderTarget: true } ),
			{ name: 'color-0' },
			{ name: 'depth-0' }
		);
		expect( renderer.setRenderTargetTextures ).toHaveBeenCalledTimes( 1 );
		expect( renderer.setRenderTarget ).toHaveBeenCalledTimes( 1 );
		expect( renderer.setRenderTargetFramebuffer ).not.toHaveBeenCalled();
	} );

	test( 'updates user and XR cameras, depth range, and restores perspective settings on end', async () => {
		const manager = new WebXRManager( createRenderer(), createGL() );
		const session = createSession();
		await startBaseSession( manager, session );
		const camera = new PerspectiveCamera( 60, 1, 0.1, 1000 );
		camera.zoom = 2;
		camera.layers.set( 3 );
		session.runNextAnimationFrame( 1, makeFrame( session ) );

		manager.updateCamera( camera );

		const cameraXR = manager.getCamera();
		expect( cameraXR.near ).toBe( 0.1 );
		expect( cameraXR.far ).toBe( 1000 );
		expect( cameraXR.cameras[ 0 ].near ).toBe( 0.1 );
		expect( cameraXR.cameras[ 1 ].far ).toBe( 1000 );
		expect( cameraXR.layers.isEnabled( 0 ) ).toBe( false );
		expect( cameraXR.layers.isEnabled( 1 ) ).toBe( true );
		expect( cameraXR.layers.isEnabled( 2 ) ).toBe( true );
		expect( cameraXR.layers.isEnabled( 3 ) ).toBe( true );
		expect( cameraXR.cameras[ 0 ].isEnabled( 1 ) ).toBe( true );
		expect( cameraXR.cameras[ 0 ].isEnabled( 2 ) ).toBe( false );
		expect( cameraXR.cameras[ 1 ].isEnabled( 2 ) ).toBe( true );
		const depthUpdates = () => session.updateRenderState.mock.calls
			.map( ( [ state ] ) => state )
			.filter( ( state ) => 'depthNear' in state );
		expect( depthUpdates() ).toEqual( [ { depthNear: 0.1, depthFar: 1000 } ] );
		expect( camera.fov ).toBeCloseTo( 90 );
		expect( camera.zoom ).toBe( 1 );

		manager.updateCamera( camera );
		expect( depthUpdates() ).toHaveLength( 1 );

		camera.near = 0.2;
		manager.updateCamera( camera );
		expect( depthUpdates() ).toHaveLength( 2 );
		expect( depthUpdates()[ 1 ] ).toEqual( { depthNear: 0.2, depthFar: 1000 } );

		session.emit( 'end' );
		expect( camera.fov ).toBe( 60 );
		expect( camera.zoom ).toBe( 2 );
	} );

	test( 'initializes depth sensing from GPU depth data and exposes its mesh and range', async () => {
		const manager = new WebXRManager( createRenderer(), createGL() );
		const session = createSession();
		session.enabledFeatures = [ 'depth-sensing' ];
		session.depthUsage = 'gpu-optimized';
		const binding = await startProjectionSession( manager, session );
		const depthSource = { name: 'depth-source-texture' };
		binding.depthInformation = {
			isValid: true,
			texture: depthSource,
			depthNear: 0.2,
			depthFar: 15
		};
		const frame = makeFrame( session, { views: [ makeView( 0 ), makeView( 1 ) ] } );

		session.runNextAnimationFrame( 1, frame );

		expect( binding.getDepthInformation ).toBeDefined();
		expect( manager.hasDepthSensing() ).toBe( true );
		expect( manager.getDepthTexture() ).toBeInstanceOf( ExternalTexture );
		expect( manager.getDepthTexture().sourceTexture ).toBe( depthSource );
		const mesh = manager.getDepthSensingMesh();
		expect( mesh ).not.toBeNull();
		expect( mesh.material.uniforms.depthColor.value ).toBe( manager.getDepthTexture() );
		expect( mesh.material.uniforms.depthWidth.value ).toBe( 800 );
		expect( mesh.material.uniforms.depthHeight.value ).toBe( 800 );

		const camera = new PerspectiveCamera( 60, 1, 0.1, 1000 );
		manager.updateCamera( camera );
		expect( session.updateRenderState ).toHaveBeenLastCalledWith( { depthNear: 0.2, depthFar: 15 } );

		session.emit( 'end' );
		expect( manager.hasDepthSensing() ).toBe( false );
		expect( manager.getDepthTexture() ).toBeNull();
		expect( manager.getDepthSensingMesh() ).toBeNull();
	} );

	test( 'exposes and caches camera-access textures during the animation loop', async () => {
		const renderer = createRenderer();
		const manager = new WebXRManager( renderer, createGL() );
		const session = createSession();
		session.enabledFeatures = [ 'camera-access' ];
		const binding = await startProjectionSession( manager, session );
		const viewCamera = { name: 'view-camera' };
		const firstImage = { name: 'first-camera-image' };
		const secondImage = { name: 'second-camera-image' };
		binding.cameraImages.set( viewCamera, firstImage );
		const firstView = makeView( 0 );
		firstView.camera = viewCamera;
		const secondView = makeView( 1 );

		session.runNextAnimationFrame( 1, makeFrame( session, { views: [ firstView, secondView ] } ) );

		const texture = manager.getCameraTexture( viewCamera );
		expect( texture ).toBeInstanceOf( ExternalTexture );
		expect( texture.sourceTexture ).toBe( firstImage );
		expect( manager.getCameraTexture( secondView.camera ) ).toBeUndefined();
		expect( renderer.state.unbindTexture ).toHaveBeenCalledTimes( 1 );

		binding.cameraImages.set( viewCamera, secondImage );
		session.runNextAnimationFrame( 2, makeFrame( session, { views: [ firstView, secondView ] } ) );

		expect( manager.getCameraTexture( viewCamera ) ).toBe( texture );
		expect( texture.sourceTexture ).toBe( secondImage );
		expect( renderer.state.unbindTexture ).toHaveBeenCalledTimes( 2 );

		session.emit( 'end' );
		expect( manager.getCameraTexture( viewCamera ) ).toBeUndefined();
	} );

	test( 'warns when framebuffer scale or reference space type changes during presentation', async () => {
		const manager = new WebXRManager( createRenderer(), createGL() );
		const session = createSession();
		await startBaseSession( manager, session );
		const warning = jest.spyOn( console, 'warn' ).mockImplementation( () => {} );

		manager.setFramebufferScaleFactor( 0.5 );
		manager.setReferenceSpaceType( 'local' );

		expect( warning ).toHaveBeenCalledTimes( 2 );
		expect( warning.mock.calls[ 0 ][ 0 ] ).toContain( 'Cannot change framebuffer scale while presenting' );
		expect( warning.mock.calls[ 1 ][ 0 ] ).toContain( 'Cannot change reference space type while presenting' );
	} );

} );
