							};
							projects.unshift( newProj );
							if ( ! firstImportedProject ) firstImportedProject = newProj;
							importedCount ++;

						}

					}

				} else if ( Array.isArray( parsed ) ) {

					for ( const proj of parsed ) {

						if ( proj && Array.isArray( proj.tabs ) && proj.tabs.length > 0 ) {

