		text = text.replace( /:::\s*(?:api-class|api-group)\s+([^\n]+)/gi, '$1\n' );
		text = text.replace( /:::\s*api\s+([^\n]+)/gi, '$1\n' );
		text = text.replace( /:::/g, ' ' );
		text = text.replace( /\[open\]/gi, '' );

