			.replace( /\[([^\]]+)\]\([^)]+\)/g, '$1' ) // Remove links keeping text
			.replace( /\*\*([^*]+)\*\*/g, '$1' ) // Remove bold
			.replace( /__([^_]+)__/g, '$1' )
			.replace( /\*([^*]+)\*/g, '$1' ) // Remove italic
			.replace( /_([^_]+)_/g, '$1' )
			.replace( /`([^`]+)`/g, '$1' ) // Remove inline code
			.replace( /#{1,6}\s+/g, '' ) // Remove headers
			.replace( />\s+/g, '' ) // Remove blockquotes
