				};

				this.playgroundTabs.push( tab );

			}

			if ( ! targetTabName ) {

				targetTabName = name;

			}

		}

		if ( targetTabName ) {

			this.renderPlaygroundTabs();
			this.activatePlaygroundTab( targetTabName );

		}

	}

