	const document = new FakeDocument();
	const window = new FakeWindow();
	const history = {
		calls: [],
		replaceState( state, title, url ) {

			this.calls.push( { state, title, url } );
			window.replaceState( state, title, url );

		},
		pushState( state, title, url ) {

			this.calls.push( { state, title, url } );

		}

	};

	globalThis.document = document;
	globalThis.window = window;
	globalThis.history = history;

	return { document, window, history, body: document.body };

}

function createElement( tagName = 'div', properties = {} ) {

	const element = new FakeElement( tagName );
	Object.assign( element, properties );
	if ( properties.className ) element.className = properties.className;
	if ( properties.id ) element.id = properties.id;
	if ( properties.style ) Object.assign( element.style, properties.style );
	return element;

}

function appendElement( parent, tagName = 'div', properties = {} ) {

	const element = createElement( tagName, properties );
	parent.appendChild( element );
	return element;

}

