		const manager = new HistoryManager( guide );

		manager.pushState( 'only' );
		manager.undo();
		expect( manager.index ).toBe( 0 );
		expect( fixture.window.location.hash ).toBe( '' );

		manager.redo();
		expect( manager.index ).toBe( 0 );
		expect( fixture.window.location.hash ).toBe( '' );

