import { jest } from '@jest/globals';
import { setConsoleFunction, getConsoleFunction } from 'three';
import { ConsoleManager } from '../../../../tsl/js/managers/ConsoleManager.js';
import { createDomFixture, createElement } from './domTestUtils.js';

class FakeRunner {

	constructor() {

		this.listeners = new Map();
		this.dispatched = [];
		this.addEventListener = jest.fn( ( type, listener ) => {

			if ( ! this.listeners.has( type ) ) this.listeners.set( type, [] );
			this.listeners.get( type ).push( listener );

		} );
		this.removeEventListener = jest.fn( ( type, listener ) => {

			const list = this.listeners.get( type ) || [];
			const index = list.indexOf( listener );
			if ( index !== - 1 ) list.splice( index, 1 );

		} );

	}

	dispatchEvent( event ) {

		this.dispatched.push( event );
		for ( const listener of this.listeners.get( event.type ) || [] ) listener( event );
		return true;

	}

	emit( type, data = {} ) {

		return this.dispatchEvent( { type, ...data } );

	}

}

function makeGuide() {

	const dom = {
		consoleErrorMessage: createElement( 'div' ),
		editorConsole: createElement( 'div', { className: 'minimized' } ),
		consoleToggleIcon: createElement( 'i' ),
		consoleToggleBtn: createElement( 'button' ),
		consoleClearBtn: createElement( 'button' ),
		consoleCopyBtn: createElement( 'button' )
	};
	const codeEditor = {
		layout: jest.fn(),
		clearMarkers: jest.fn(),
		setErrorMarker: jest.fn(),
		revealLine: jest.fn(),
		focus: jest.fn()
	};
	const runner = new FakeRunner();
	const guide = {
		dom,
		runner,
		codeEditor,
		isPlaygroundActive: false,
		updateDebugWGSL: jest.fn(),
		createIcons: jest.fn()
	};
	return { guide, dom, runner, codeEditor };

}

describe( 'ConsoleManager', () => {

	let fixture;
	let manager;
	let errorSpy;
	let warnSpy;
	let context;

	beforeEach( () => {

		fixture = createDomFixture();
		setConsoleFunction( () => {} );
		context = makeGuide();
		errorSpy = jest.spyOn( console, 'error' ).mockImplementation( () => {} );
		warnSpy = jest.spyOn( console, 'warn' ).mockImplementation( () => {} );
	} );

	afterEach( () => {

		manager?.dispose();
		manager = null;
		jest.restoreAllMocks();
		setConsoleFunction( () => {} );
		delete globalThis.navigator;

	} );

	it( 'installs console overrides and subscribes the manager listeners on construction', () => {

		manager = new ConsoleManager( context.guide );

		expect( console.error ).not.toBe( errorSpy );
		expect( console.warn ).not.toBe( warnSpy );
		expect( context.runner.addEventListener ).toHaveBeenCalledTimes( 6 );
		expect( context.runner.addEventListener.mock.calls.map( call => call[ 0 ] ) ).toEqual( [
			'start', 'log', 'warn-log', 'error-log', 'success', 'error'
		] );
		expect( typeof getConsoleFunction() ).toBe( 'function' );

	} );

	it( 'forwards three console output with serialization and filters internal stack traces', () => {

		manager = new ConsoleManager( context.guide );
		const consoleFn = getConsoleFunction();

		consoleFn( 'log', 'hello', { a: 1 } );
		expect( context.runner.dispatched[ 0 ] ).toEqual( { type: 'log', message: 'hello {"a":1}' } );

		consoleFn( 'error', 'THREE.Problem', { code: 7 } );
		expect( context.runner.dispatched[ 1 ] ).toMatchObject( {
			type: 'error-log',
			message: 'Problem {"code":7}',
			line: null,
			column: null,
			errorMsg: 'Problem {"code":7}'
		} );

		const stackTrace = {
			isStackTrace: true,
			stack: [
				{ file: 'other.js', line: 90, column: 1 },
				{ file: 'playground-eval.js', line: 10, column: 4 }
			]
		};
		consoleFn( 'warn', 'Something wrong foo.js:12', stackTrace );
		expect( context.runner.dispatched[ 2 ] ).toEqual( {
			type: 'warn-log',
			message: 'Line 8: Something wrong',
			line: 8,
			column: 4,
			errorMsg: 'Something wrong'
		} );
		expect( JSON.stringify( context.runner.dispatched[ 2 ] ) ).not.toContain( 'isStackTrace' );

	} );

	it( 'ignores styled console messages and the noop log type falls back to a log event', () => {

		manager = new ConsoleManager( context.guide );
		const consoleFn = getConsoleFunction();

		consoleFn( 'warn', '%cstyled message' );
		expect( context.runner.dispatched ).toHaveLength( 0 );

		consoleFn( 'info', 'plain' );
		expect( context.runner.dispatched[ 0 ] ).toMatchObject( { type: 'log', message: 'plain' } );

	} );

	it( 'deduplicates messages already emitted by the three console hook within a microtask', async () => {

		manager = new ConsoleManager( context.guide );
		const consoleFn = getConsoleFunction();

		consoleFn( 'warn', 'Duplicated' );
		console.warn( 'Duplicated' );
		expect( context.runner.dispatched ).toHaveLength( 1 );

		await Promise.resolve();
		console.warn( 'Duplicated' );
		expect( context.runner.dispatched ).toHaveLength( 2 );

	} );

	it( 'routes direct console.error and console.warn calls as colored log events', () => {

		manager = new ConsoleManager( context.guide );

		console.error( 'Direct', { id: 2 } );
		expect( context.runner.dispatched[ 0 ] ).toMatchObject( {
			type: 'error-log',
			message: 'Direct {"id":2}',
			line: null,
			column: null,
			errorMsg: 'Direct {"id":2}'
		} );

		console.error( new Error( 'Boom' ) );
		expect( context.runner.dispatched[ 1 ] ).toMatchObject( {
			type: 'error-log',
			message: 'Boom',
			errorMsg: 'Boom'
		} );

		console.warn( { warning: true }, 'Careful' );
		expect( context.runner.dispatched[ 2 ] ).toEqual( { type: 'warn-log', message: '{"warning":true} Careful' } );

		console.error( '%cnot forwarded' );
		expect( context.runner.dispatched ).toHaveLength( 3 );

	} );

	it( 'appends colored console lines and enables clear/copy buttons', () => {

		manager = new ConsoleManager( context.guide );

		manager.log( 'plain' );
		manager.warn( 'careful' );
		manager.error( 'bad' );

		const lines = context.dom.consoleErrorMessage.querySelectorAll( '.console-line' );
		expect( lines ).toHaveLength( 3 );
		expect( lines.map( line => line.querySelector( '.console-line-text' ).textContent ) ).toEqual( [ 'plain', 'careful', 'bad' ] );
		expect( lines.map( line => line.style.color ) ).toEqual( [ '#e2e8f0', '#fde047', '#fca5a5' ] );
		expect( context.dom.consoleClearBtn.hasAttribute( 'disabled' ) ).toBe( false );
		expect( context.dom.consoleCopyBtn.hasAttribute( 'disabled' ) ).toBe( false );
		expect( context.dom.consoleErrorMessage.scrollTop ).toBe( context.dom.consoleErrorMessage.scrollHeight );

		manager.clearConsole();
		expect( context.dom.consoleErrorMessage.childElementCount ).toBe( 0 );
		expect( context.dom.consoleClearBtn.getAttribute( 'disabled' ) ).toBe( 'true' );
		expect( context.dom.consoleCopyBtn.getAttribute( 'disabled' ) ).toBe( 'true' );

	} );

	it( 'keeps only the most recent 100 console lines', () => {

		manager = new ConsoleManager( context.guide );
		for ( let i = 0; i < 105; i ++ ) manager.log( `line-${i}` );

		const lines = context.dom.consoleErrorMessage.querySelectorAll( '.console-line-text' );
		expect( lines ).toHaveLength( 100 );
		expect( lines[ 0 ].textContent ).toBe( 'line-5' );
		expect( lines[ 99 ].textContent ).toBe( 'line-104' );

	} );

	it( 'toggles console minimization and updates the icon and editor layouts', () => {

		manager = new ConsoleManager( context.guide );

		manager.toggleConsole();
		expect( context.dom.editorConsole.classList.contains( 'minimized' ) ).toBe( true );
		expect( context.dom.consoleToggleIcon.getAttribute( 'data-icon' ) ).toBe( 'chevron-up' );
		expect( context.guide.createIcons ).toHaveBeenCalledWith( context.dom.consoleToggleBtn );
		expect( context.codeEditor.layout ).toHaveBeenCalled();

		manager.toggleConsole();
		expect( context.dom.editorConsole.classList.contains( 'minimized' ) ).toBe( false );
		expect( context.dom.consoleToggleIcon.getAttribute( 'data-icon' ) ).toBe( 'chevron-down' );

		manager.toggleConsole( true );
		expect( context.dom.editorConsole.classList.contains( 'minimized' ) ).toBe( true );

	} );

	it( 'renders runner events, adds a jump button, reveals the line, and marks errors', () => {

		manager = new ConsoleManager( context.guide );

		context.runner.emit( 'log', { message: 'hello' } );
		expect( context.dom.editorConsole.classList.contains( 'minimized' ) ).toBe( false );
		expect( context.dom.consoleErrorMessage.querySelector( '.console-line-text' ).textContent ).toBe( 'hello' );

		context.runner.emit( 'warn-log', { message: 'careful', line: 4, column: 2 } );
		const warning = context.dom.consoleErrorMessage.querySelectorAll( '.console-line' )[ 1 ];
		expect( warning.style.color ).toBe( '#fde047' );
		const jump = warning.querySelector( '.console-jump-btn' );
		expect( jump ).not.toBeNull();
		jump.onclick( { stopPropagation: jest.fn() } );
		expect( context.codeEditor.revealLine ).toHaveBeenCalledWith( 4, 2 );

		context.runner.emit( 'error-log', { message: 'Line 5: broken', line: 5, column: 3, errorMsg: 'broken' } );
		expect( context.codeEditor.setErrorMarker ).toHaveBeenCalledWith( 5, 3, 'broken' );

	} );

	it( 'handles runner lifecycle events for start, success, and error', () => {

		jest.useFakeTimers();
		manager = new ConsoleManager( context.guide );
		context.runner.emit( 'log', { message: 'existing' } );

		context.runner.emit( 'start' );
		expect( context.dom.consoleErrorMessage.textContent ).toBe( '' );
		expect( context.codeEditor.clearMarkers ).toHaveBeenCalled();

		context.guide.isPlaygroundActive = true;
		context.runner.emit( 'success' );
		expect( context.guide.updateDebugWGSL ).toHaveBeenCalledTimes( 1 );
		expect( context.dom.editorConsole.classList.contains( 'minimized' ) ).toBe( true );
		jest.advanceTimersByTime( 500 );
		expect( context.guide.updateDebugWGSL ).toHaveBeenCalledTimes( 2 );

		const error = new Error( 'runtime failure' );
		context.runner.emit( 'error', { message: 'failed', line: 9, column: 1, error } );
		expect( context.codeEditor.setErrorMarker ).toHaveBeenCalledWith( 9, 1, error.toString() );
		expect( context.dom.editorConsole.classList.contains( 'minimized' ) ).toBe( false );

	} );

	it( 'copies visible console text and temporarily shows success feedback', async () => {

		jest.useFakeTimers();
		const writeText = jest.fn().mockResolvedValue( undefined );
		Object.defineProperty( globalThis, 'navigator', {
			configurable: true,
			value: { clipboard: { writeText } }
		} );
		manager = new ConsoleManager( context.guide );
		manager.log( 'first' );
		manager.log( 'second' );

		manager.copyConsole();
		expect( writeText ).toHaveBeenCalledWith( 'first\nsecond' );
		await Promise.resolve();

		expect( context.dom.consoleCopyBtn.classList.contains( 'success' ) ).toBe( true );
		expect( context.dom.consoleCopyBtn.innerHTML ).toContain( 'check' );
		expect( context.guide.createIcons ).toHaveBeenCalledWith( context.dom.consoleCopyBtn );

		jest.advanceTimersByTime( 2000 );
		expect( context.dom.consoleCopyBtn.classList.contains( 'success' ) ).toBe( false );
		expect( context.dom.consoleCopyBtn.innerHTML ).toContain( 'copy' );

	} );

	it( 'does not touch the clipboard when the console is empty', () => {

		const writeText = jest.fn();
		Object.defineProperty( globalThis, 'navigator', {
			configurable: true,
			value: { clipboard: { writeText } }
		} );
		manager = new ConsoleManager( context.guide );

		manager.copyConsole();
		expect( writeText ).not.toHaveBeenCalled();

	} );

	it( 'disposes the overrides and unsubscribes all runner listeners', () => {

		const currentError = console.error;
		const currentWarn = console.warn;
		manager = new ConsoleManager( context.guide );

		manager.dispose();

		expect( console.error ).toBe( currentError );
		expect( console.warn ).toBe( currentWarn );
		expect( context.runner.removeEventListener ).toHaveBeenCalledTimes( 6 );
		expect( Array.from( context.runner.listeners.values() ).every( list => list.length === 0 ) ).toBe( true );
		manager = null;

	} );

} );
