		expect( guide.dom.contentCol.children ).toContain( guide.dom.editorConsole );
		expect( guide.dom.vResizer.style.display ).toBe( 'block' );
		expect( guide.dom.previewSection.style.height ).toBe( '50%' );
		expect( guide.dom.debugContainer.style.display ).toBe( 'flex' );
		expect( guide.dom.contentCol.style.width ).toBe( '50%' );
		expect( guide.dom.editorCol.style.width ).toBe( '50%' );
		expect( guide.dom.hResizer.classList.contains( 'collapsed' ) ).toBe( false );
		expect( guide.setResizerToggleIcon ).toHaveBeenCalledWith( 'chevron-right' );
		expect( manager.updateDebugWGSL ).toHaveBeenCalled();
		expect( context.codeEditor.layout ).toHaveBeenCalled();
		expect( guide.updateUI ).toHaveBeenCalled();

		manager.togglePlayground( true );
		expect( guide.updateUI ).toHaveBeenCalledTimes( 1 );

	} );

