		manager.togglePlayground( false );

		expect( guide.isPlaygroundActive ).toBe( false );
		expect( fixture.body.classList.contains( 'playground-mode' ) ).toBe( false );
		expect( guide.dom.debugContainer.style.display ).toBe( 'none' );
		expect( guide.dom.contentArea.style.display ).toBe( '' );
		expect( guide.dom.previewSection.style.height ).toBe( '' );
		expect( guide.dom.codeContainer.parentElement.className ).toContain( 'editor-workspace' );
		expect( guide.layoutManager.updateVResizerIcons ).toHaveBeenCalledWith( '' );
		expect( context.codeEditor.setReadOnly ).toHaveBeenCalledWith( false );
		expect( context.codeEditor.layout ).toHaveBeenCalled();
		expect( guide.updateUI ).toHaveBeenCalledTimes( 2 );

	} );

	it( 'uses the mobile workspace layout when entering playground mode on a narrow screen', () => {

		fixture.window.innerWidth = 500;
		manager.updateDebugWGSL = jest.fn();
		guide.dom.previewSection.style.height = '60%';

		manager.togglePlayground( true );

		expect( context.dom.contentCol.style.width ).toBe( '0%' );
		expect( context.dom.contentCol.style.display ).toBe( 'none' );
		expect( context.dom.editorCol.style.width ).toBe( '100%' );
		expect( context.dom.editorCol.style.display ).toBe( 'flex' );
		expect( context.dom.previewSection.style.height ).toBe( '' );
		expect( context.dom.debugContainer.style.display ).toBe( 'none' );
		expect( manager.updateDebugWGSL ).not.toHaveBeenCalled();

	} );

	it( 'renders tabs, read-only indicators, add/action controls, and highlights the active tab', () => {

		jest.useFakeTimers();
