		expect( context.dom.tabsBar.querySelector( '.playground-tab.active .playground-tab-label' ).textContent ).toBe( 'script1' );
		expect( context.dom.tabsBar.querySelector( '.playground-tab-lock-icon' ) ).not.toBeNull();
		expect( context.dom.tabsBar.querySelector( '.playground-tab-add' ).textContent ).toBe( '+' );
		expect( context.dom.tabsBar.querySelector( '.playground-projects-btn' ) ).not.toBeNull();
		expect( context.dom.tabsBar.querySelector( '.playground-imported-files-btn' ) ).not.toBeNull();
		expect( context.dom.tabsBar.querySelector( '.playground-clean-btn' ) ).not.toBeNull();
		expect( context.dom.tabsBar.querySelector( '.playground-undo-btn' ) ).not.toBeNull();
		expect( context.dom.tabsBar.querySelector( '.playground-redo-btn' ) ).not.toBeNull();
		expect( context.dom.tabsBar.querySelector( '.playground-refresh-btn' ) ).not.toBeNull();
		expect( guide.historyManager.updateButtons ).toHaveBeenCalled();
		expect( context.dom.tabsBar.querySelector( '.playground-tab.active' ).lastScrollIntoView ).toBeDefined();

	} );

	it( 'hides the tab bar when the playground is inactive and creates default tabs when needed', () => {

		manager.renderPlaygroundTabs();
		expect( context.dom.tabsBar.style.display ).toBe( 'none' );

