		expect( manager.activePlaygroundTabName ).toBe( 'main' );
		expect( manager.initialTabsSnapshot ).toBe( JSON.stringify( [ { name: 'main', code: '// Play here!\n' } ] ) );

	} );

	it( 'activates a tab after preserving the current editor contents', () => {

		manager.playgroundTabs = [
			{ name: 'main', code: 'original main' },
			{ name: 'script1', code: 'one' }
		];
		manager.activePlaygroundTabName = 'main';
		context.codeEditor.getValue.mockReturnValue( 'edited main' );
