		manager.updatePlaygroundHash = jest.fn();

		manager.activatePlaygroundTab( 'script1' );

		expect( manager.playgroundTabs[ 0 ].code ).toBe( 'edited main' );
		expect( manager.activePlaygroundTabName ).toBe( 'script1' );
		expect( context.codeEditor.setReadOnly ).toHaveBeenCalledWith( false );
		expect( context.codeEditor.setValue ).toHaveBeenCalledWith( 'one' );
